                SafeSet(humanoid, "WalkSpeed", value)
            end
        end,
    })

    attributesSection:AddSlider("UniversalJumpPower", {
        Title = "Jumppower",
        Min = 0,
        Max = 250,
        Default = initialJumpPower,
        Increment = 1,
        Flag = "UniversalJumpPower",
        Callback = function(value: number)
            local humanoid = CurrentHumanoid()
            if humanoid then
                RememberHumanoid(humanoid)
                SafeSet(humanoid, "UseJumpPower", true)
                SafeSet(humanoid, "JumpPower", value)
            end
        end,
    })

    attributesSection:AddSlider("UniversalGravity", {
        Title = "Gravity",
        Min = 0,
        Max = 300,
        Default = initialGravity,
        Increment = 1,
        Flag = "UniversalGravity",
        Callback = function(value: number)
            SafeSet(Workspace, "Gravity", value)
        end,
    })

    local visualsTab = window:AddTab({ Title = "Visuals" })
    local espSection = visualsTab:AddSection("Player ESP")

    espSection:AddToggle("UniversalEspBox", {
        Title = "Box",
        Default = true,
        Flag = "UniversalEspBox",
    })
    espSection:AddToggle("UniversalEspName", {
        Title = "Name",
        Default = true,
        Flag = "UniversalEspName",
    })
    espSection:AddToggle("UniversalEspDistance", {
        Title = "Distance",
        Default = true,
        Flag = "UniversalEspDistance",
    })
    espSection:AddToggle("UniversalPlayerEsp", {
        Title = "Player ESP",
        Description = "Shows other players through walls using the selected details.",
        Default = false,
        Flag = "UniversalPlayerEsp",
        Callback = function(enabled: boolean)
            if enabled then
                StartEsp()
            else
                StopEsp()
            end
        end,
    })

    local miscTab = window:AddTab({ Title = "Misc" })
    local utilitySection = miscTab:AddSection("Utilities")

    utilitySection:AddToggle("UniversalAntiAfk", {
        Title = "Anti-AFK",
        Description = "Prevents the Roblox idle timeout.",
        Default = false,
        Flag = "UniversalAntiAfk",
        Callback = function(enabled: boolean)
            if enabled then
                StartAntiAfk()
            else
                StopAntiAfk()
            end
        end,
    })

    utilitySection:AddToggle("UniversalFpsBoost", {
        Title = "FPS Boost",
        Description = "Temporarily reduces expensive materials, effects, and shadows.",
        Default = false,
        Flag = "UniversalFpsBoost",
        Callback = function(enabled: boolean)
            if enabled then
                StartFpsBoost()
            else
                StopFpsBoost()
            end
        end,
    })

    local serverSection = miscTab:AddSection("Server")
    serverSection:AddButton({
        Title = "Server Hop",
        Description = "Joins a different non-full public server.",
        Callback = ServerHop,
    })
    serverSection:AddButton({
        Title = "Rejoin",
        Description = "Reconnects to the current server instance.",
        Callback = Rejoin,
    })

    local Cleanup: () -> ()
    Cleanup = function()
        if runtime.Destroyed then
            return
        end
        runtime.Destroyed = true

        StopFly()
        StopNoclip()
        StopAntiAfk()
        StopEsp()
        StopFpsBoost()

        for humanoid, original in runtime.HumanoidOriginals do
            if humanoid.Parent then
                SafeSet(humanoid, "WalkSpeed", original.WalkSpeed)
                SafeSet(humanoid, "JumpPower", original.JumpPower)
                SafeSet(humanoid, "UseJumpPower", original.UseJumpPower)
                SafeSet(humanoid, "AutoRotate", original.AutoRotate)
                SafeSet(humanoid, "PlatformStand", original.PlatformStand)
            end
        end
        table.clear(runtime.HumanoidOriginals)
        SafeSet(Workspace, "Gravity", originalGravity)

        for _, connection in runtime.Connections do
            connection:Disconnect()
        end
        table.clear(runtime.Connections)
    end

    activeCleanup = Cleanup
    activeWindow = window
    Track(window.Instance.Destroying:Connect(function()
        Cleanup()
        if activeCleanup == Cleanup then
            activeCleanup = nil
        end
        if activeWindow == window then
            activeWindow = nil
        end
    end))

    return window
end

function module.Destroy()
    if activeCleanup then
        activeCleanup()
        activeCleanup = nil
    end
    if activeWindow and activeWindow.Destroy then
        activeWindow:Destroy()
        activeWindow = nil
    end
end

return module
]=]

-- Module: loader/init.lua (dependencies: loader/keysystem, loader/registry, loader/utils)
__bundle_sources["loader/init"] = [=[
--[[
    5AM Hub
    File: loader/init.lua

    Authenticates the client, loads the shared UI, discovers game modules,
    initializes matching modules, and exposes structured lifecycle results.
]]

local STANDALONE_BUNDLE_URL = "https://raw.githack.com/HoolHool69/5am-hub/main/dist/loader.lua"

local function HasModuleLoaderContext(): boolean
    if typeof(script) ~= "Instance" then
        return false
    end

    local parent = script.Parent
    return script:FindFirstChild("utils") ~= nil
        or (parent ~= nil and parent:FindFirstChild("utils") ~= nil)
end

local function BootstrapStandalone(): any
    local environment: any = _G
    local environmentSuccess, localEnvironment = pcall(function()
        return getfenv(0)
    end)
    if environmentSuccess and type(localEnvironment) == "table" then
        environment = localEnvironment
    end
    local baseEnvironment = environment

    local getGlobalEnvironment = environment.getgenv
    if type(getGlobalEnvironment) == "function" then
        local globalSuccess, globalEnvironment = pcall(getGlobalEnvironment)
        if globalSuccess and type(globalEnvironment) == "table" then
            environment = setmetatable({}, {
                __index = function(_table, key)
                    local localValue = baseEnvironment[key]
                    return if localValue ~= nil then localValue else globalEnvironment[key]
                end,
            })
        end
    end

    local bundleUrl = if type(environment.FiveAMBundleUrl) == "string"
            and environment.FiveAMBundleUrl ~= ""
        then environment.FiveAMBundleUrl
        else STANDALONE_BUNDLE_URL

    local fetchSuccess, sourceOrError = pcall(function()
        return game:HttpGet(bundleUrl)
    end)
    if not fetchSuccess or type(sourceOrError) ~= "string" then
        error(string.format("5AM Hub could not download its standalone bundle: %s", tostring(sourceOrError)), 0)
    end

    local compiler = environment.loadstring or loadstring
    if type(compiler) ~= "function" then
        error("5AM Hub requires an executor with loadstring support", 0)
    end

    local compiledChunk, compileError = compiler(sourceOrError)
    if type(compiledChunk) ~= "function" then
        error(string.format("5AM Hub bundle compilation failed: %s", tostring(compileError)), 0)
    end

    local runSuccess, loaderOrError = pcall(compiledChunk)
    if not runSuccess then
        error(string.format("5AM Hub bundle startup failed: %s", tostring(loaderOrError)), 0)
    end
    return loaderOrError
end

-- A raw loadstring has no ModuleScript hierarchy. Redirect that execution path
-- to the generated standalone artifact. The bundler defines the lexical marker
-- below so its embedded copy of this module does not bootstrap recursively.
if __FIVE_AM_BUNDLED ~= true and not HasModuleLoaderContext() then
    return BootstrapStandalone()
end

local function FindLoaderModule(name: string): any
    return script:FindFirstChild(name) or script.Parent:FindFirstChild(name)
end

local utilsModule = "loader/utils" -- bundled module reference
local keySystemModule = "loader/keysystem" -- bundled module reference
local registryModule = "loader/registry" -- bundled module reference
local Utils = __bundle_require("loader/utils")
local KeySystem = __bundle_require("loader/keysystem")
local Registry = __bundle_require("loader/registry")

local Loader = {}
Loader.__index = Loader

local function Result(success: boolean, stage: string, code: string, message: string, extra: any?): any
    local result = extra or {}
    result.Success = success
    result.Stage = stage
    result.Code = code
    result.Message = message
    return result
end

local function ResolveProjectRoot(): any?
    if typeof(script) ~= "Instance" then
        return nil
    end

    local candidates = {
        script.Parent,
        script.Parent.Parent,
    }

    for _, candidate in candidates do
        if candidate and candidate:FindFirstChild("ui") and candidate:FindFirstChild("games") then
            return candidate
        end
    end

    return script.Parent
end

local function ResolveUiReference(options: any, projectRoot: any): any?
    if options.UI ~= nil then
        return options.UI
    end

    return if projectRoot then projectRoot:FindFirstChild("ui") else nil
end

local function ValidateUi(ui: any): (boolean, string?)
    if type(ui) ~= "table" then
        return false, "UI module must return a table"
    end

    if type(ui.CreateWindow) ~= "function" or type(ui.Unload) ~= "function" then
        return false, "UI module does not expose the required lifecycle API"
    end

    if type(ui.Flags) ~= "table" then
        return false, "UI module does not expose UI.Flags"
    end

    return true
end

function Loader.new(): any
    return setmetatable({
        State = "Idle",
        Authentication = nil,
        UI = nil,
        Registry = nil,
        Discovery = nil,
        GameResult = nil,
        Options = nil,
        _starting = false,

        Utils = Utils,
        KeySystem = KeySystem,
        RegistryClass = Registry,
    }, Loader)
end

function Loader:Authenticate(key: any?): any
    return self.KeySystem:Authenticate(key)
end

function Loader:Start(options: any?): any
    options = Utils:Merge({
        Key = nil,
        UI = nil,
        GamesRoot = nil,
        Registry = nil,
        Manifest = nil,
        PlaceId = nil,
        WaitForGameLoaded = true,
    }, options)

    if self._starting then
        return Result(false, self.State, "LOADER_ALREADY_STARTING", "The loader is already starting")
    end

    if self.State == "Ready" then
        return Result(true, "Ready", "LOADER_ALREADY_READY", "The loader is already initialized", {
            Authentication = self.Authentication,
            Discovery = self.Discovery,
            Game = self.GameResult,
            UI = self.UI,
        })
    end

    self._starting = true
    self.Options = options

    if options.WaitForGameLoaded and not Utils:WaitForGameLoaded() then
        self._starting = false
        self.State = "Failed"
        return Result(false, "Game", "GAME_NOT_READY", "The Roblox client did not finish loading")
    end

    self.State = "Authenticating"
    local providedKey = Utils:GetProvidedKey(options)
    local authentication = self:Authenticate(providedKey)
    self.Authentication = authentication

    if not authentication.Success then
        self._starting = false
        self.State = "AuthenticationFailed"
        return Result(false, "Authentication", authentication.Code, authentication.Message, {
            Authentication = authentication,
        })
    end

    self.State = "LoadingUI"
    local projectRoot = ResolveProjectRoot()
    local uiReference = ResolveUiReference(options, projectRoot)

    if not uiReference then
        self._starting = false
        self.State = "Failed"
        return Result(false, "UI", "UI_MODULE_NOT_FOUND", "The shared UI module could not be found", {
            Authentication = authentication,
        })
    end

    local uiLoadSuccess, uiOrError = Utils:SafeRequire(uiReference)
    if not uiLoadSuccess then
        self._starting = false
        self.State = "Failed"
        return Result(false, "UI", "UI_MODULE_LOAD_FAILED", tostring(uiOrError), {
            Authentication = authentication,
        })
    end

    local uiValid, uiValidationError = ValidateUi(uiOrError)
    if not uiValid then
        self._starting = false
        self.State = "Failed"
        return Result(false, "UI", "UI_CONTRACT_INVALID", uiValidationError or "Invalid UI module", {
            Authentication = authentication,
        })
    end

    self.UI = uiOrError
    self.State = "DiscoveringGames"

    local gamesRoot = options.GamesRoot
        or (if projectRoot then projectRoot:FindFirstChild("games") else nil)
    local registry = options.Registry or self.Registry

    if type(registry) ~= "table" or type(registry.Initialize) ~= "function" then
        registry = Registry.new(gamesRoot)
    elseif gamesRoot and type(registry.SetGamesRoot) == "function" then
        registry:SetGamesRoot(gamesRoot)
    end

    self.Registry = registry

    local discoveryResult: any
    if type(registry.Discover) == "function" then
        local discoverySuccess, discoveredOrError = Utils:SafeCall(registry.Discover, registry)
        discoveryResult = if discoverySuccess and type(discoveredOrError) == "table"
            then discoveredOrError
            else Result(false, "Discovery", "DISCOVERY_FAILED", tostring(discoveredOrError))
    else
        discoveryResult = Result(true, "Discovery", "DISCOVERY_SKIPPED", "The supplied registry does not use discovery")
    end
    self.Discovery = discoveryResult

    local manifestResult = nil
    if options.Manifest ~= nil and type(registry.LoadManifest) == "function" then
        local manifestSuccess, loadedOrError = Utils:SafeCall(registry.LoadManifest, registry, options.Manifest)
        manifestResult = if manifestSuccess and type(loadedOrError) == "table"
            then loadedOrError
            else Result(false, "Manifest", "MANIFEST_LOAD_FAILED", tostring(loadedOrError))
    end

    self.State = "InitializingGame"
    local placeId = tonumber(options.PlaceId) or Utils:GetPlaceId()
    local gameSuccess, initializedOrError = Utils:SafeCall(registry.Initialize, registry, placeId, self.UI, self)
    local gameResult = if gameSuccess and type(initializedOrError) == "table"
        then initializedOrError
        else Result(false, "Game", "GAME_INITIALIZATION_FAILED", tostring(initializedOrError))
    self.GameResult = gameResult

    self._starting = false
    self.State = "Ready"

    local hasWarnings = not discoveryResult.Success
        or (manifestResult ~= nil and not manifestResult.Success)
        or not gameResult.Success

    return Result(true, "Ready", if hasWarnings then "LOADER_READY_WITH_WARNINGS" else "LOADER_READY", if hasWarnings
        then "5AM Hub initialized with one or more non-fatal module warnings"
        else "5AM Hub initialized successfully", {
        Authentication = authentication,
        Discovery = discoveryResult,
        Manifest = manifestResult,
        Game = gameResult,
        PlaceId = placeId,
        GameName = Utils:GetGameName(),
        UI = self.UI,
    })
end

function Loader:RegisterGame(placeId: any, moduleReference: any, metadata: any?): (boolean, string?)
    if not self.Registry then
        self.Registry = Registry.new(nil)
    end

    return self.Registry:Register(placeId, moduleReference, metadata)
end

function Loader:GetState(): string
    return self.State
end

function Loader:Unload(): any
    if self.UI and type(self.UI.Unload) == "function" then
        local unloadSuccess, unloadError = Utils:SafeCall(self.UI.Unload, self.UI)
        if not unloadSuccess then
            return Result(false, "Unload", "UI_UNLOAD_FAILED", tostring(unloadError))
        end
    end

    self.State = "Idle"
    self.Authentication = nil
    self.UI = nil
    self.Registry = nil
    self.Discovery = nil
    self.GameResult = nil
    self.Options = nil
    self._starting = false

    return Result(true, "Unload", "LOADER_UNLOADED", "5AM Hub was unloaded")
end

return Loader.new()
]=]

-- Module: loader/keysystem.lua (dependencies: loader/utils)
__bundle_sources["loader/keysystem"] = [=[
--[[
    5AM Hub
    File: loader/keysystem.lua

    Temporary development authentication isolated from loader startup so it
    can be replaced by the production key provider without changing callers.
]]

local Utils = __bundle_require("loader/utils")

local KeySystem = {
    DevelopmentKey = "5AM-DEV",
}

local function Result(success: boolean, code: string, message: string): any
    return {
        Success = success,
        Code = code,
        Message = message,
    }
end

local function NormalizeKey(key: any): string?
    if type(key) ~= "string" then
        return nil
    end

    local normalized = string.match(key, "^%s*(.-)%s*$") or ""
    return if normalized == "" then nil else normalized
end

function KeySystem:IsDevelopmentMode(): boolean
    return Utils:GetEnvironment().FiveAMDevMode == true
end

function KeySystem:ValidateDevelopmentKey(key: any): any
    local normalizedKey = NormalizeKey(key)

    if normalizedKey == self.DevelopmentKey then
        return Result(true, "DEVELOPMENT_KEY_ACCEPTED", "Development key accepted")
    end

    return Result(false, "INVALID_DEVELOPMENT_KEY", "Invalid key. Use the current development key.")
end

function KeySystem:ValidateKey(key: any): any
    -- Future Luarmor authentication request should be integrated here,
    -- replacing only this development validator while preserving the result contract.
    return self:ValidateDevelopmentKey(key)
end

function KeySystem:PromptForKey(): any
    local screenGui = Utils:Create("ScreenGui", {
        Name = "FiveAMHubKeyPrompt",
        DisplayOrder = 1000,
        IgnoreGuiInset = true,
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Global,
    })

    local parentSuccess, parentError = Utils:ParentGui(screenGui)
    if not parentSuccess then
        screenGui:Destroy()
        return Result(false, "KEY_UI_UNAVAILABLE", parentError or "Unable to display the key prompt")
    end

    local overlay = Utils:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(10, 10, 14),
        BackgroundTransparency = 0.28,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 1,
    }, screenGui)

    local card = Utils:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = Color3.fromRGB(24, 22, 31),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(360, 224),
        ZIndex = 2,
    }, overlay)
    Utils:Create("UICorner", { CornerRadius = UDim.new(0, 10) }, card)
    Utils:Create("UIStroke", {
        Color = Color3.fromRGB(68, 55, 88),
        Thickness = 1,
    }, card)

    Utils:Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = Enum.Font.GothamBold,
        Position = UDim2.fromOffset(18, 15),
        Size = UDim2.new(1, -56, 0, 24),
        Text = "5AM Hub",
        TextColor3 = Color3.fromRGB(247, 244, 252),
        TextSize = 17,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 3,
    }, card)

    Utils:Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = Enum.Font.Gotham,
        Position = UDim2.fromOffset(18, 43),
        Size = UDim2.new(1, -36, 0, 35),
        Text = "Enter the temporary development key to continue.",
        TextColor3 = Color3.fromRGB(190, 179, 207),
        TextSize = 12,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        ZIndex = 3,
    }, card)

    local closeButton = Utils:Create("TextButton", {
        AnchorPoint = Vector2.new(1, 0),
        AutoButtonColor = false,
        BackgroundTransparency = 1,
        Font = Enum.Font.Gotham,
        Position = UDim2.new(1, -10, 0, 10),
        Size = UDim2.fromOffset(28, 28),
        Text = "×",
        TextColor3 = Color3.fromRGB(190, 179, 207),
        TextSize = 20,
        ZIndex = 4,
    }, card)

    local keyInput = Utils:Create("TextBox", {
        BackgroundColor3 = Color3.fromRGB(37, 29, 52),
        ClearTextOnFocus = false,
        Font = Enum.Font.Gotham,
        PlaceholderColor3 = Color3.fromRGB(112, 101, 128),
        PlaceholderText = "Development key",
        Position = UDim2.fromOffset(18, 86),
        Size = UDim2.new(1, -36, 0, 40),
        Text = "",
        TextColor3 = Color3.fromRGB(247, 244, 252),
        TextSize = 14,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 3,
    }, card)
    Utils:Create("UICorner", { CornerRadius = UDim.new(0, 7) }, keyInput)
    Utils:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 11),
        PaddingRight = UDim.new(0, 11),
    }, keyInput)

    local statusLabel = Utils:Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = Enum.Font.Gotham,
        Position = UDim2.fromOffset(18, 130),
        Size = UDim2.new(1, -36, 0, 24),
        Text = "",
        TextColor3 = Color3.fromRGB(248, 113, 113),
        TextSize = 12,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 3,
    }, card)

    local submitButton = Utils:Create("TextButton", {
        AutoButtonColor = false,
        BackgroundColor3 = Color3.fromRGB(139, 92, 246),
        Font = Enum.Font.GothamBold,
        Position = UDim2.fromOffset(18, 166),
        Size = UDim2.new(1, -36, 0, 40),
        Text = "Continue",
        TextColor3 = Color3.fromRGB(255, 255, 255),
        TextSize = 14,
        ZIndex = 3,
    }, card)
    Utils:Create("UICorner", { CornerRadius = UDim.new(0, 7) }, submitButton)

    local resultEvent = Instance.new("BindableEvent")
    local connections = {}
    local completed = false
    local finalResult = Result(false, "KEY_PROMPT_CLOSED", "Authentication was cancelled")

    local function Complete(result: any)
        if completed then
            return
        end

        completed = true
        finalResult = result
        resultEvent:Fire()
    end

    local function Submit()
        local validationResult = self:ValidateKey(keyInput.Text)

        if validationResult.Success then
            statusLabel.Text = validationResult.Message
            statusLabel.TextColor3 = Color3.fromRGB(52, 211, 153)
            Complete(validationResult)
        else
            statusLabel.Text = validationResult.Message
            statusLabel.TextColor3 = Color3.fromRGB(248, 113, 113)
            keyInput:CaptureFocus()
        end
    end

    table.insert(connections, submitButton.Activated:Connect(Submit))
    table.insert(connections, closeButton.Activated:Connect(function()
        Complete(Result(false, "KEY_PROMPT_CANCELLED", "Authentication was cancelled"))
    end))
    table.insert(connections, keyInput.FocusLost:Connect(function(enterPressed: boolean)
        if enterPressed then
            Submit()
        end
    end))
    table.insert(connections, screenGui.Destroying:Connect(function()
        Complete(Result(false, "KEY_PROMPT_DESTROYED", "The authentication prompt was closed"))
    end))

    task.defer(function()
        if not completed and keyInput.Parent then
            keyInput:CaptureFocus()
        end
    end)

    resultEvent.Event:Wait()
    Utils:DisconnectAll(connections)
    resultEvent:Destroy()
    screenGui:Destroy()

    return finalResult
end

function KeySystem:Authenticate(providedKey: any?): any
    if self:IsDevelopmentMode() then
        return Result(true, "DEVELOPMENT_MODE_ENABLED", "Authenticated through FiveAMDevMode")
    end

    local normalizedKey = NormalizeKey(providedKey)
    if not normalizedKey then
        return self:PromptForKey()
    end

    return self:ValidateKey(normalizedKey)
end

return KeySystem
]=]

-- Module: loader/registry.lua (dependencies: loader/utils)
__bundle_sources["loader/registry"] = [=[
--[[
    5AM Hub
    File: loader/registry.lua

    Discovers universal and place-specific game modules, validates the shared
    module contract, and initializes matching modules with structured results.
]]

local Utils = __bundle_require("loader/utils")

local Registry = {}
Registry.__index = Registry

local function Result(success: boolean, code: string, message: string, extra: any?): any
    local result = extra or {}
    result.Success = success
    result.Code = code
    result.Message = message
    return result
end

local function ResolveContainerModule(container: any): any?
    if typeof(container) ~= "Instance" then
        return container
    end

    if container:IsA("ModuleScript") then
        return container
    end

    local initModule = container:FindFirstChild("init")
    if initModule and initModule:IsA("ModuleScript") then
        return initModule
    end

    return nil
end

function Registry.new(gamesRoot: any?): any
    return setmetatable({
        _gamesRoot = gamesRoot,
        _entries = {},
        _universal = nil,
    }, Registry)
end

function Registry:SetGamesRoot(gamesRoot: any?)
    self._gamesRoot = gamesRoot
end

function Registry:Register(placeId: any, moduleReference: any, metadata: any?): (boolean, string?)
    local numericPlaceId = tonumber(placeId)
    local resolvedModule = ResolveContainerModule(moduleReference)

    if not numericPlaceId or numericPlaceId <= 0 then
        return false, "Place ID must be a positive number"
    end

    if not resolvedModule then
        return false, "Game module could not be resolved"
    end

    self._entries[numericPlaceId] = {
        PlaceId = numericPlaceId,
        Module = resolvedModule,
        Metadata = if type(metadata) == "table" then metadata else {},
    }

    return true
end

function Registry:RegisterUniversal(moduleReference: any): (boolean, string?)
    local resolvedModule = ResolveContainerModule(moduleReference)
    if not resolvedModule then
        return false, "Universal module could not be resolved"
    end

    self._universal = resolvedModule
    return true
end

function Registry:_ResolveNamedModule(moduleName: string): any?
    local gamesRoot = self._gamesRoot
    if typeof(gamesRoot) ~= "Instance" then
        return nil
    end

    local container = gamesRoot:FindFirstChild(moduleName)
    return if container then ResolveContainerModule(container) else nil
end

function Registry:Discover(): any
    local gamesRoot = self._gamesRoot
    if typeof(gamesRoot) ~= "Instance" then
        return Result(false, "GAMES_ROOT_UNAVAILABLE", "The games container is unavailable", {
            Registered = 0,
        })
    end

    local getChildrenSuccess, children = pcall(function()
        return gamesRoot:GetChildren()
    end)

    if not getChildrenSuccess then
        return Result(false, "GAME_DISCOVERY_FAILED", tostring(children), {
            Registered = 0,
        })
    end

    local registered = 0
    local warnings = {}

    for _, child in children do
        if child.Name == "_universal" then
            local success, message = self:RegisterUniversal(child)
            if not success then
                table.insert(warnings, message)
            end
        elseif child.Name ~= "_template" then
            local placeIdText = string.match(child.Name, "^(%d+)_") or string.match(child.Name, "^(%d+)$")

            if placeIdText then
                local success, message = self:Register(tonumber(placeIdText), child, {
                    Name = child.Name,
                })

                if success then
                    registered += 1
                elseif message then
                    table.insert(warnings, string.format("%s: %s", child.Name, message))
                end
            end
        end
    end

    return Result(true, "DISCOVERY_COMPLETE", "Game module discovery completed", {
        Registered = registered,
        HasUniversal = self._universal ~= nil,
        Warnings = warnings,
    })
end

function Registry:LoadManifest(manifest: any): any
    local decodedManifest = manifest

    if type(manifest) == "string" then
        local serviceSuccess, httpService = pcall(function()
            return game:GetService("HttpService")
        end)

        if not serviceSuccess then
            return Result(false, "HTTP_SERVICE_UNAVAILABLE", "HttpService is unavailable for local JSON decoding")
        end

        local decodeSuccess, decoded = pcall(function()
            return httpService:JSONDecode(manifest)
        end)

        if not decodeSuccess then
            return Result(false, "MANIFEST_INVALID", tostring(decoded))
        end

        decodedManifest = decoded
    end

    if type(decodedManifest) ~= "table" then
        return Result(false, "MANIFEST_INVALID", "Manifest must be a table or JSON object")
    end

    local entries = decodedManifest.Games or decodedManifest
    if type(entries) ~= "table" then
        return Result(false, "MANIFEST_INVALID", "Manifest Games must be a table")
    end

    local registered = 0
    local warnings = {}

    for key, entry in entries do
        if key ~= "_comment" and key ~= "Games" then
            local placeId = key
            local moduleReference = entry
            local metadata = nil

            if type(entry) == "table" and not entry.Init then
                placeId = entry.PlaceId or entry.PlaceID or key
                moduleReference = entry.Module or entry.Path or entry.Name
                metadata = entry.Meta or entry.Metadata
            end

            if key == "_universal" then
                if type(moduleReference) == "string" then
                    moduleReference = self:_ResolveNamedModule(moduleReference)
                end

                local success, message = self:RegisterUniversal(moduleReference)
                if not success and message then
                    table.insert(warnings, message)
                end
            else
                if type(moduleReference) == "string" then
                    moduleReference = self:_ResolveNamedModule(moduleReference)
                end

                local success, message = self:Register(placeId, moduleReference, metadata)
                if success then
                    registered += 1
                elseif message then
                    table.insert(warnings, string.format("%s: %s", tostring(placeId), message))
                end
            end
        end
    end

    return Result(true, "MANIFEST_LOADED", "Manifest entries were processed", {
        Registered = registered,
        Warnings = warnings,
    })
end

function Registry:Resolve(placeId: any): any?
    local numericPlaceId = tonumber(placeId)
    local entry = if numericPlaceId then self._entries[numericPlaceId] else nil
    return if entry then entry.Module else self._universal
end

function Registry:GetModules(placeId: any): {any}
    local modules = {}

    if self._universal then
        table.insert(modules, {
            Kind = "Universal",
            Module = self._universal,
        })
    end

    local numericPlaceId = tonumber(placeId)
    local entry = if numericPlaceId then self._entries[numericPlaceId] else nil
    if entry and entry.Module ~= self._universal then
        table.insert(modules, {
            Kind = "Game",
            Module = entry.Module,
            PlaceId = numericPlaceId,
            Metadata = entry.Metadata,
        })
    end

    return modules
end

function Registry:LoadModule(moduleReference: any): any
    local loadSuccess, loadedOrError = Utils:SafeRequire(moduleReference)
    if not loadSuccess then
        return Result(false, "MODULE_LOAD_FAILED", tostring(loadedOrError))
    end

    if type(loadedOrError) ~= "table" then
        return Result(false, "MODULE_CONTRACT_INVALID", "Game module must return a table")
    end

    if type(loadedOrError.Meta) ~= "table" then
        return Result(false, "MODULE_CONTRACT_INVALID", "Game module must expose a Meta table")
    end

    if type(loadedOrError.Init) ~= "function" then
        return Result(false, "MODULE_CONTRACT_INVALID", "Game module must expose Init(UI, Loader)")
    end

    return Result(true, "MODULE_LOADED", "Game module loaded", {
        Module = loadedOrError,
    })
end

function Registry:Initialize(placeId: any, ui: any, loader: any): any
    local loadedModules = {}
    local errors = {}
    local candidates = self:GetModules(placeId)

    for _, candidate in candidates do
        local loadResult = self:LoadModule(candidate.Module)

        if not loadResult.Success then
            table.insert(errors, {
                Kind = candidate.Kind,
                Code = loadResult.Code,
                Message = loadResult.Message,
            })
        else
            local initializeSuccess, initializeError = Utils:SafeCall(loadResult.Module.Init, ui, loader)

            if initializeSuccess then
                table.insert(loadedModules, {
                    Kind = candidate.Kind,
                    Meta = loadResult.Module.Meta,
                })
            else
                table.insert(errors, {
                    Kind = candidate.Kind,
                    Code = "MODULE_INITIALIZATION_FAILED",
                    Message = tostring(initializeError),
                })
            end
        end
    end

    local success = #errors == 0
    local code = if #candidates == 0 then "NO_MATCHING_MODULE" elseif success then "MODULES_INITIALIZED" else "MODULE_ERRORS"
    local message = if #candidates == 0
        then "No universal or place-specific game module is registered"
        elseif success
        then "Matching game modules initialized"
        else "One or more game modules failed to initialize"

    return Result(success, code, message, {
        Loaded = loadedModules,
        Errors = errors,
    })
end

function Registry:List(): {any}
    local entries = {}

    for placeId, entry in self._entries do
        table.insert(entries, {
            PlaceId = placeId,
            Metadata = entry.Metadata,
        })
    end

    table.sort(entries, function(left, right)
        return left.PlaceId < right.PlaceId
    end)

    return entries
end

return Registry
]=]

-- Module: loader/utils.lua (dependencies: none)
__bundle_sources["loader/utils"] = [=[
--[[
    5AM Hub
    File: loader/utils.lua

    Shared executor-safe helpers used by the loader, authentication prompt,
    and game registry. No helper performs external network requests.
]]

local Utils = {}

function Utils:GetEnvironment(): {[string]: any}
    local success, environment = pcall(function()
        return getfenv(0)
    end)

    if not success or type(environment) ~= "table" then
        return {}
    end

    local getGlobalEnvironment = environment.getgenv
    if type(getGlobalEnvironment) == "function" then
        local globalSuccess, globalEnvironment = pcall(getGlobalEnvironment)

        if globalSuccess and type(globalEnvironment) == "table" then
            return setmetatable({}, {
                __index = function(_table, key)
                    local localValue = environment[key]
                    return if localValue ~= nil then localValue else globalEnvironment[key]
                end,
            }) :: {[string]: any}
        end
    end

    return environment :: {[string]: any}
end

function Utils:GetGlobalFunction(name: string): any?
    local candidate = self:GetEnvironment()[name]
    return if type(candidate) == "function" then candidate else nil
end

function Utils:Merge(defaults: any, overrides: any?): any
    local merged = {}

    if type(defaults) == "table" then
        for key, value in defaults do
            merged[key] = value
        end
    end

    if type(overrides) == "table" then
        for key, value in overrides do
            merged[key] = value
        end
    end

    return merged
end

function Utils:SafeCall(callback: any, ...: any): (boolean, any)
    if type(callback) ~= "function" then
        return false, "Callback is not callable"
    end

    local arguments = table.pack(...)
    return pcall(function()
        return callback(table.unpack(arguments, 1, arguments.n))
    end)
end

function Utils:Create(className: string, properties: any?, parent: any?): any
    local instance: any = Instance.new(className)

    if type(properties) == "table" then
        for property, value in properties do
            pcall(function()
                instance[property] = value
            end)
        end
    end

    if parent ~= nil then
        instance.Parent = parent
    end

    return instance
end

function Utils:ResolveGuiParents(): {any}
    local parents = {}
    local environment = self:GetEnvironment()
    local getHiddenUi = environment.gethui

    if type(getHiddenUi) == "function" then
        local success, hiddenUi = pcall(getHiddenUi)
        if success and hiddenUi then
            table.insert(parents, hiddenUi)
        end
    end

    local coreSuccess, coreGui = pcall(function()
        return game:GetService("CoreGui")
    end)
    if coreSuccess and coreGui then
        table.insert(parents, coreGui)
    end

    local playerSuccess, playerGui = pcall(function()
        local players = game:GetService("Players")
        local localPlayer = players.LocalPlayer
        return if localPlayer then localPlayer:FindFirstChildOfClass("PlayerGui") else nil
    end)
    if playerSuccess and playerGui then
        table.insert(parents, playerGui)
    end

    return parents
end

function Utils:ParentGui(guiObject: any): (boolean, string?)
    for _, guiParent in self:ResolveGuiParents() do
        local success = pcall(function()
            guiObject.Parent = guiParent
        end)

        if success and guiObject.Parent == guiParent then
            local protectGui = self:GetGlobalFunction("protectgui")
                or self:GetGlobalFunction("protect_gui")

            if protectGui then
                pcall(protectGui, guiObject)
            end

            return true
        end
    end

    return false, "No writable GUI parent is available"
end

function Utils:SafeRequire(moduleReference: any): (boolean, any)
    if type(moduleReference) == "table" then
        return true, moduleReference
    end

    if type(moduleReference) == "function" then
        return self:SafeCall(moduleReference)
    end

    if typeof(moduleReference) ~= "Instance" or not moduleReference:IsA("ModuleScript") then
        return false, "Module reference is not a ModuleScript, table, or function"
    end

    return pcall(require, moduleReference)
end

function Utils:GetPlaceId(): number
    local success, placeId = pcall(function()
        return game.PlaceId
    end)

    return if success and type(placeId) == "number" then placeId else 0
end

function Utils:GetGameName(): string
    local success, gameName = pcall(function()
        return game.Name
    end)

    return if success then tostring(gameName) else "Unknown Game"
end

function Utils:GetProvidedKey(options: any?): string?
    if type(options) == "table" and type(options.Key) == "string" and options.Key ~= "" then
        return options.Key
    end

    local environment = self:GetEnvironment()
    local environmentKey = environment.FiveAMKey or environment.HubKey
    if (type(environmentKey) ~= "string" or environmentKey == "") and type(environment._G) == "table" then
        environmentKey = environment._G.FiveAMKey or environment._G.HubKey
    end
    if type(environmentKey) == "string" and environmentKey ~= "" then
        return environmentKey
    end

    return nil
end

function Utils:WaitForGameLoaded(): boolean
    local loadedSuccess, isLoaded = pcall(function()
        return game:IsLoaded()
    end)

    if not loadedSuccess then
        return false
    end

    if not isLoaded then
        local waitSuccess = pcall(function()
            game.Loaded:Wait()
        end)

        return waitSuccess
    end

    return true
end

function Utils:DisconnectAll(connections: {any})
    for _, connection in connections do
        pcall(function()
            connection:Disconnect()
        end)
    end

    table.clear(connections)
end

return Utils
]=]

-- Module: ui/components/Button.lua (dependencies: none)
__bundle_sources["ui/components/Button"] = [=[
--[[
    5AM Hub
    File: ui/components/Button.lua

    Click action with hover, pressed, disabled, and activation feedback states.
]]

local Button = {}
Button.__index = Button

function Button.new(ui: any, section: any, options: any): any
    options = ui:_MergeOptions({
        Title = "Button",
        Description = "",
        Callback = nil,
        Disabled = false,
    }, options)

    local self = setmetatable({
        _ui = ui,
        _section = section,
        _enabled = options.Disabled ~= true,
        _hovered = false,
        _pressed = false,
        _title = tostring(options.Title),
        _description = tostring(options.Description or ""),
        _actionCallback = options.Callback,
    }, Button)
    ui:_InitializeValueComponent(self, options, false)
    self.Activated = ui.Signal.new()

    local rowHeight = if self._description == "" then 44 else 58
    local row = ui:_Create("TextButton", {
        Name = "Button",
        AutoButtonColor = false,
        BackgroundTransparency = 0,
        LayoutOrder = #section._components + 1,
        Size = UDim2.new(1, 0, 0, rowHeight),
        Text = "",
        ZIndex = 15,
    }, section._componentContainer)
    self.Instance = row
    self._stroke = ui:_AddStroke(row, 1)
    ui:_AddCorner(row, 7)

    local titleLabel = ui:_Create("TextLabel", {
        Name = "Title",
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, if self._description == "" then 0 else 8),
        Size = UDim2.new(1, -50, 0, if self._description == "" then rowHeight else 20),
        Text = self._title,
        TextSize = ui.Config.TextSize,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 16,
    }, row)
    self._titleLabel = titleLabel

    local descriptionLabel = ui:_Create("TextLabel", {
        Name = "Description",
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, 29),
        Size = UDim2.new(1, -50, 0, 17),
        Text = self._description,
        TextSize = ui.Config.TextSize - 2,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = self._description ~= "",
        ZIndex = 16,
    }, row)
    self._descriptionLabel = descriptionLabel

    local actionLabel = ui:_Create("TextLabel", {
        Name = "Action",
        AnchorPoint = Vector2.new(1, 0.5),
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.new(1, -13, 0.5, 0),
        Size = UDim2.fromOffset(20, 24),
        Text = "›",
        TextSize = 22,
        ZIndex = 16,
    }, row)
    self._actionLabel = actionLabel

    local function ApplyVisualState()
        if self._destroyed then
            return
        end

        local theme = ui:GetTheme()
        local background = theme.Element

        if not self._enabled then
            background = theme.BackgroundSecondary
        elseif self._pressed then
            background = theme.ElementActive
        elseif self._hovered then
            background = theme.ElementHover
        end

        ui.Tween:Create(row, "Snap", { BackgroundColor3 = background })
        titleLabel.TextColor3 = if self._enabled then theme.Text else theme.DisabledText
        descriptionLabel.TextColor3 = if self._enabled then theme.SubText else theme.DisabledText
        actionLabel.TextColor3 = if self._enabled then theme.Accent else theme.DisabledText
        self._stroke.Color = theme.Border
    end
    self._applyVisualState = ApplyVisualState

    ui:_Connect(self, row.MouseEnter, function()
        self._hovered = true
        ApplyVisualState()
    end)
    ui:_Connect(self, row.MouseLeave, function()
        self._hovered = false
        self._pressed = false
        ApplyVisualState()
    end)
    ui:_Connect(self, row.MouseButton1Down, function()
        self._pressed = true
        ApplyVisualState()
    end)
    ui:_Connect(self, row.MouseButton1Up, function()
        self._pressed = false
        ApplyVisualState()
    end)
    ui:_Connect(self, row.Activated, function()
        self:Fire()
    end)

    ui:_ObserveTheme(self, function()
        ApplyVisualState()
    end)

    return self
end

function Button.Set(self: any, enabled: any)
    local normalized = enabled == true
    if self._enabled == normalized then
        self._applyVisualState()
        return
    end

    self._enabled = normalized
    self._applyVisualState()
    self.Changed:Fire(self._enabled)
end

function Button.Get(self: any): boolean
    return self._enabled
end

function Button.OnChanged(self: any, callback: any): any?
    return self._ui:_OnChanged(self, callback)
end

function Button.OnActivated(self: any, callback: any): any?
    if self._destroyed or type(callback) ~= "function" then
        return nil
    end

    local connection = self.Activated:Connect(function()
        self._ui:_SafeCall(callback)
    end)
    return self._ui:_TrackConnection(self, connection)
end

function Button.SetTitle(self: any, title: any)
    self._title = tostring(title or "")
    self._titleLabel.Text = self._title
end

function Button.SetDescription(self: any, description: any)
    self._description = tostring(description or "")
    self._descriptionLabel.Text = self._description
    self._descriptionLabel.Visible = self._description ~= ""
    local rowHeight = if self._description == "" then 44 else 58
    self.Instance.Size = UDim2.new(1, 0, 0, rowHeight)
    self._titleLabel.Position = UDim2.fromOffset(12, if self._description == "" then 0 else 8)
    self._titleLabel.Size = UDim2.new(1, -50, 0, if self._description == "" then rowHeight else 20)
end

function Button.SetDisabled(self: any, disabled: any)
    self:Set(disabled ~= true)
end

function Button.Fire(self: any): boolean
    if self._destroyed or not self._enabled then
        return false
    end

    self._pressed = true
    self._applyVisualState()

    task.delay(0.08, function()
        if not self._destroyed then
            self._pressed = false
            self._applyVisualState()
        end
    end)

    self._ui:_SafeCall(self._actionCallback)
    self.Activated:Fire()
    return true
end

function Button.Destroy(self: any)
    if self._destroyed then
        return
    end

    local index = table.find(self._section._components, self)
    if index then
        table.remove(self._section._components, index)
    end

    self.Activated:Disconnect()
    self._ui:_CleanupComponent(self)
end

return Button
]=]

-- Module: ui/components/Colorpicker.lua (dependencies: none)
__bundle_sources["ui/components/Colorpicker"] = [=[
--[[
    5AM Hub
    File: ui/components/Colorpicker.lua

    HSV color picker with saturation/value, hue, optional transparency,
    hexadecimal input, mouse/touch interaction, themes, and flag persistence.
]]

local Colorpicker = {}
Colorpicker.__index = Colorpicker

local function Clamp(value: number, minimum: number, maximum: number): number
    return math.max(minimum, math.min(maximum, value))
end

local function ColorToHex(color: Color3): string
    return string.format(
        "#%02X%02X%02X",
        math.round(color.R * 255),
        math.round(color.G * 255),
        math.round(color.B * 255)
    )
end

local function HexToColor(value: string): Color3?
    local hex = string.gsub(value, "#", "")
    if #hex ~= 6 or not string.match(hex, "^%x%x%x%x%x%x$") then
        return nil
    end

    local red = tonumber(string.sub(hex, 1, 2), 16)
    local green = tonumber(string.sub(hex, 3, 4), 16)
    local blue = tonumber(string.sub(hex, 5, 6), 16)

    if not red or not green or not blue then
        return nil
    end

    return Color3.fromRGB(red, green, blue)
end

local function NormalizeColor(value: any): (Color3?, number?)
    if typeof(value) == "Color3" then
        return value, nil
    end

    if type(value) == "string" then
        return HexToColor(value), nil
    end

    if type(value) == "table" then
        local nestedColor = value.Color or value[1]
        if typeof(nestedColor) == "Color3" then
            return nestedColor, tonumber(value.Transparency or value[2])
        end

        if tonumber(value.R) and tonumber(value.G) and tonumber(value.B) then
            local red = tonumber(value.R) :: number
            local green = tonumber(value.G) :: number
            local blue = tonumber(value.B) :: number

            if red > 1 or green > 1 or blue > 1 then
                return Color3.fromRGB(red, green, blue), tonumber(value.Transparency)
            end

            return Color3.new(red, green, blue), tonumber(value.Transparency)
        end
    end

    return nil, nil
end

function Colorpicker.new(ui: any, section: any, options: any): any
    options = ui:_MergeOptions({
        Title = "Colorpicker",
        Description = "",
        Default = Color3.fromRGB(255, 255, 255),
        Transparency = 0,
        AllowTransparency = false,
        Flag = nil,
        Callback = nil,
        Disabled = false,
    }, options)

    local defaultColor = NormalizeColor(options.Default)
    if not defaultColor then
        defaultColor = Color3.new(1, 1, 1)
    end

    local hue, saturation, brightness = defaultColor:ToHSV()
    local self = setmetatable({
        _ui = ui,
        _section = section,
        _color = defaultColor,
        _transparency = Clamp(tonumber(options.Transparency) or 0, 0, 1),
        _allowTransparency = options.AllowTransparency == true,
        _disabled = options.Disabled == true,
        _open = false,
        _hue = hue,
        _saturation = saturation,
        _brightness = brightness,
        _pickerKind = nil,
        _pickerInput = nil,
    }, Colorpicker)
    ui:_InitializeValueComponent(self, options)

    local description = tostring(options.Description or "")
    self._closedHeight = if description == "" then 52 else 66
    self._panelHeight = if self._allowTransparency then 220 else 184

    local row = ui:_Create("Frame", {
        Name = "Colorpicker",
        BackgroundTransparency = 0,
        ClipsDescendants = true,
        LayoutOrder = #section._components + 1,
        Size = UDim2.new(1, 0, 0, self._closedHeight),
        ZIndex = 20,
    }, section._componentContainer)
    self.Instance = row
    self._stroke = ui:_AddStroke(row, 1)
    ui:_AddCorner(row, 7)

    local titleLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, if description == "" then 0 else 7),
        Size = UDim2.new(1, -78, 0, if description == "" then self._closedHeight else 20),
        Text = tostring(options.Title),
        TextSize = ui.Config.TextSize,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 21,
    }, row)
    self._titleLabel = titleLabel

    local descriptionLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, 29),
        Size = UDim2.new(1, -78, 0, 17),
        Text = description,
        TextSize = ui.Config.TextSize - 2,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = description ~= "",
        ZIndex = 21,
    }, row)
    self._descriptionLabel = descriptionLabel

    local preview = ui:_Create("TextButton", {
        AnchorPoint = Vector2.new(1, 0.5),
        AutoButtonColor = false,
        BackgroundColor3 = self._color,
        BackgroundTransparency = self._transparency,
        Position = UDim2.new(1, -12, 0, self._closedHeight / 2),
        Size = UDim2.fromOffset(48, 28),
        Text = "",
        ZIndex = 22,
    }, row)
    ui:_AddCorner(preview, 6)
    self._preview = preview
    self._previewStroke = ui:_AddStroke(preview, 1)

    local panel = ui:_Create("Frame", {
        Name = "PickerPanel",
        BackgroundTransparency = 0,
        Position = UDim2.fromOffset(10, self._closedHeight),
        Size = UDim2.new(1, -20, 0, self._panelHeight),
        Visible = false,
        ZIndex = 30,
    }, row)
    ui:_AddCorner(panel, 6)
    self._panel = panel

    local saturationValue = ui:_Create("TextButton", {
        Name = "SaturationValue",
        Active = true,
        AutoButtonColor = false,
        BackgroundColor3 = Color3.fromHSV(self._hue, 1, 1),
        ClipsDescendants = true,
        Position = UDim2.fromOffset(8, 8),
        Size = UDim2.new(1, -46, 0, 126),
        Text = "",
        ZIndex = 31,
    }, panel)
    ui:_AddCorner(saturationValue, 5)
    self._saturationValue = saturationValue

    local whiteLayer = ui:_Create("Frame", {
        BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 0,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 32,
    }, saturationValue)
    ui:_Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 1),
        }),
    }, whiteLayer)

    local blackLayer = ui:_Create("Frame", {
        BackgroundColor3 = Color3.new(0, 0, 0),
        BorderSizePixel = 0,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 33,
    }, saturationValue)
    ui:_Create("UIGradient", {
        Rotation = 90,
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(1, 0),
        }),
    }, blackLayer)

    local saturationCursor = ui:_Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = Color3.new(1, 1, 1),
        Position = UDim2.fromScale(self._saturation, 1 - self._brightness),
        Size = UDim2.fromOffset(10, 10),
        ZIndex = 34,
    }, saturationValue)
    ui:_AddCorner(saturationCursor, 5)
    ui:_AddStroke(saturationCursor, 1)
    self._saturationCursor = saturationCursor

    local hueBar = ui:_Create("TextButton", {
        Name = "Hue",
        Active = true,
        AnchorPoint = Vector2.new(1, 0),
        AutoButtonColor = false,
        BackgroundColor3 = Color3.new(1, 1, 1),
        Position = UDim2.new(1, -8, 0, 8),
        Size = UDim2.fromOffset(22, 126),
        Text = "",
        ZIndex = 31,
    }, panel)
    ui:_AddCorner(hueBar, 5)
    ui:_Create("UIGradient", {
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 0, 0)),
            ColorSequenceKeypoint.new(0.17, Color3.fromRGB(255, 255, 0)),
            ColorSequenceKeypoint.new(0.33, Color3.fromRGB(0, 255, 0)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(0, 255, 255)),
            ColorSequenceKeypoint.new(0.67, Color3.fromRGB(0, 0, 255)),
            ColorSequenceKeypoint.new(0.83, Color3.fromRGB(255, 0, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 0, 0)),
        }),
        Rotation = 90,
    }, hueBar)
    self._hueBar = hueBar

    local hueCursor = ui:_Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = Color3.new(1, 1, 1),
        Position = UDim2.fromScale(0.5, self._hue),
        Size = UDim2.new(1, 4, 0, 4),
        ZIndex = 34,
    }, hueBar)
    ui:_AddCorner(hueCursor, 2)
    self._hueCursor = hueCursor

    local hexInput = ui:_Create("TextBox", {
        Name = "Hex",
        BackgroundTransparency = 0,
        ClearTextOnFocus = false,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(8, 142),
        Size = UDim2.new(1, -16, 0, 32),
        Text = ColorToHex(self._color),
        TextSize = ui.Config.TextSize - 1,
        TextXAlignment = Enum.TextXAlignment.Center,
        ZIndex = 31,
    }, panel)
    ui:_AddCorner(hexInput, 5)
    self._hexInput = hexInput

    local transparencyBar = ui:_Create("TextButton", {
        Name = "Transparency",
        Active = true,
        AutoButtonColor = false,
        BackgroundColor3 = self._color,
        Position = UDim2.fromOffset(8, 184),
        Size = UDim2.new(1, -16, 0, 18),
        Text = "",
        Visible = self._allowTransparency,
        ZIndex = 31,
    }, panel)
    ui:_AddCorner(transparencyBar, 5)
    ui:_Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 1),
        }),
    }, transparencyBar)
    self._transparencyBar = transparencyBar

    local transparencyCursor = ui:_Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = Color3.new(1, 1, 1),
        Position = UDim2.fromScale(self._transparency, 0.5),
        Size = UDim2.fromOffset(4, 24),
        ZIndex = 32,
    }, transparencyBar)
    ui:_AddCorner(transparencyCursor, 2)
    self._transparencyCursor = transparencyCursor

    local function UpdateFromInput(kind: string, input: any)
        if self._disabled then
            return
        end

        if kind == "SaturationValue" then
            if saturationValue.AbsoluteSize.X <= 0 or saturationValue.AbsoluteSize.Y <= 0 then
                return
            end

            local saturation = Clamp((input.Position.X - saturationValue.AbsolutePosition.X) / saturationValue.AbsoluteSize.X, 0, 1)
            local value = 1 - Clamp((input.Position.Y - saturationValue.AbsolutePosition.Y) / saturationValue.AbsoluteSize.Y, 0, 1)
            self:Set(Color3.fromHSV(self._hue, saturation, value), self._transparency)
        elseif kind == "Hue" then
            if hueBar.AbsoluteSize.Y <= 0 then
                return
            end

            local hueValue = Clamp((input.Position.Y - hueBar.AbsolutePosition.Y) / hueBar.AbsoluteSize.Y, 0, 1)
            self:Set(Color3.fromHSV(hueValue, self._saturation, self._brightness), self._transparency)
        elseif kind == "Transparency" and self._allowTransparency then
            if transparencyBar.AbsoluteSize.X <= 0 then
                return
            end

            local transparency = Clamp((input.Position.X - transparencyBar.AbsolutePosition.X) / transparencyBar.AbsoluteSize.X, 0, 1)
            self:Set(self._color, transparency)
        end
    end

    local function BeginPicker(kind: string, input: any)
        local inputType = input.UserInputType
        if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
            return
        end

        self._pickerKind = kind
        self._pickerInput = input
        UpdateFromInput(kind, input)
    end

    ui:_Connect(self, saturationValue.InputBegan, function(input: any)
        BeginPicker("SaturationValue", input)
    end)
    ui:_Connect(self, hueBar.InputBegan, function(input: any)
        BeginPicker("Hue", input)
    end)
    ui:_Connect(self, transparencyBar.InputBegan, function(input: any)
        BeginPicker("Transparency", input)
    end)
    ui:_Connect(self, preview.Activated, function()
        if not self._disabled then
            if self._open then
                self:Close()
            else
                self:Open()
            end
        end
    end)
    ui:_Connect(self, hexInput.FocusLost, function()
        local parsed = HexToColor(hexInput.Text)
        if parsed then
            self:Set(parsed, self._transparency)
        else
            hexInput.Text = ColorToHex(self._color)
        end
    end)

    local userInputService = ui:_GetUserInputService()
    if userInputService then
        ui:_Connect(self, userInputService.InputChanged, function(input: any)
            if not self._pickerInput or not self._pickerKind then
                return
            end

            local activeType = self._pickerInput.UserInputType
            if (activeType == Enum.UserInputType.Touch and input == self._pickerInput)
                or (activeType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement)
            then
                UpdateFromInput(self._pickerKind, input)
            end
        end)

        ui:_Connect(self, userInputService.InputEnded, function(input: any)
            if input == self._pickerInput or (
                self._pickerInput
                and self._pickerInput.UserInputType == Enum.UserInputType.MouseButton1
                and input.UserInputType == Enum.UserInputType.MouseButton1
            ) then
                self._pickerKind = nil
                self._pickerInput = nil
            end
        end)

        ui:_Connect(self, userInputService.InputBegan, function(input: any)
            if not self._open then
                return
            end

            local inputType = input.UserInputType
            if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
                return
            end

            local position = input.Position
            local absolutePosition = row.AbsolutePosition
            local absoluteSize = row.AbsoluteSize
            local inside = position.X >= absolutePosition.X
                and position.X <= absolutePosition.X + absoluteSize.X
                and position.Y >= absolutePosition.Y
                and position.Y <= absolutePosition.Y + absoluteSize.Y

            if not inside then
                self:Close()
            end
        end)
    end

    ui:_ObserveTheme(self, function(theme: any)
        row.BackgroundColor3 = theme.Element
        titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
        descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
        panel.BackgroundColor3 = theme.BackgroundSecondary
        hexInput.BackgroundColor3 = theme.Element
        hexInput.TextColor3 = theme.Text
        saturationCursor.BackgroundColor3 = theme.Text
        hueCursor.BackgroundColor3 = theme.Text
        transparencyCursor.BackgroundColor3 = theme.Text
        self._stroke.Color = theme.Border
        self._previewStroke.Color = theme.Border
    end)

    ui:_BindFlag(self, options.Flag, self:_GetFlagValue())
    self:_UpdateVisuals()
    return self
end

function Colorpicker._GetFlagValue(self: any): any
    if self._allowTransparency then
        return {
            Color = self._color,
            Transparency = self._transparency,
        }
    end

    return self._color
end

function Colorpicker._UpdateVisuals(self: any)
    self._preview.BackgroundColor3 = self._color
    self._preview.BackgroundTransparency = self._transparency
    self._saturationValue.BackgroundColor3 = Color3.fromHSV(self._hue, 1, 1)
    self._saturationCursor.Position = UDim2.fromScale(self._saturation, 1 - self._brightness)
    self._hueCursor.Position = UDim2.fromScale(0.5, self._hue)
    self._transparencyBar.BackgroundColor3 = self._color
    self._transparencyCursor.Position = UDim2.fromScale(self._transparency, 0.5)

    if not self._hexInput:IsFocused() then
        self._hexInput.Text = ColorToHex(self._color)
    end
end

function Colorpicker.Set(self: any, value: any, transparency: any?)
    local color, embeddedTransparency = NormalizeColor(value)
    if not color then
        return
    end

    local normalizedTransparency = self._transparency
    if self._allowTransparency then
        normalizedTransparency = Clamp(
            tonumber(transparency) or embeddedTransparency or self._transparency,
            0,
            1
        )
    else
        normalizedTransparency = 0
    end

    local changed = self._color ~= color or self._transparency ~= normalizedTransparency
    self._color = color
    self._transparency = normalizedTransparency
    self._hue, self._saturation, self._brightness = color:ToHSV()
    self:_UpdateVisuals()

    if changed then
        self._ui:_UpdateFlag(self, self:_GetFlagValue())
        self.Changed:Fire(self._color, self._transparency)
    end
end

function Colorpicker.Get(self: any)
    if self._allowTransparency then
        return self._color, self._transparency
    end

    return self._color
end

function Colorpicker.OnChanged(self: any, callback: any): any?
    return self._ui:_OnChanged(self, callback)
end

function Colorpicker.Open(self: any)
    if self._destroyed or self._disabled or self._open then
        return
    end

    self._open = true
    self._panel.Visible = true
    self._ui.Tween:Create(self.Instance, "Smooth", {
        Size = UDim2.new(1, 0, 0, self._closedHeight + self._panelHeight + 8),
    })
end

function Colorpicker.Close(self: any)
    if not self._open then
        return
    end

    self._open = false
    self._panel.Visible = false
    self._pickerKind = nil
    self._pickerInput = nil
    self._ui.Tween:Create(self.Instance, "Smooth", {
        Size = UDim2.new(1, 0, 0, self._closedHeight),
    })
end

function Colorpicker.SetDisabled(self: any, disabled: any)
    self._disabled = disabled == true
    if self._disabled then
        self:Close()
    end

    local theme = self._ui:GetTheme()
    self._titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
    self._descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
end

function Colorpicker.Destroy(self: any)
    if self._destroyed then
        return
    end

    self._pickerKind = nil
    self._pickerInput = nil

    local index = table.find(self._section._components, self)
    if index then
        table.remove(self._section._components, index)
    end

    self._ui:_CleanupComponent(self)
end

return Colorpicker
]=]

-- Module: ui/components/Dropdown.lua (dependencies: none)
__bundle_sources["ui/components/Dropdown"] = [=[
--[[
    5AM Hub
    File: ui/components/Dropdown.lua

    Searchable single- or multi-select dropdown with dynamic option layout,
    outside-click dismissal, theme updates, and persistent flag values.
]]

local Dropdown = {}
Dropdown.__index = Dropdown

local OPTION_HEIGHT = 30
local OPTION_SPACING = 4
local MAX_VISIBLE_OPTIONS = 5

local function ContainsValue(values: {any}, target: any): boolean
    return table.find(values, target) ~= nil
end

local function SelectionText(selection: any, multi: boolean): string
    if multi then
        if #selection == 0 then
            return "Select..."
        end

        local labels = {}
        for _, value in selection do
            table.insert(labels, tostring(value))
        end
        return table.concat(labels, ", ")
    end

    return if selection == nil then "Select..." else tostring(selection)
end

function Dropdown.new(ui: any, section: any, options: any): any
    options = ui:_MergeOptions({
        Title = "Dropdown",
        Description = "",
        Values = {},
        Default = nil,
        Multi = false,
        Searchable = false,
        Flag = nil,
        Callback = nil,
        Disabled = false,
    }, options)

    local values = {}
    if type(options.Values) == "table" then
        for _, value in options.Values do
            table.insert(values, value)
        end
    end

    local self = setmetatable({
        _ui = ui,
        _section = section,
        _values = values,
        _multi = options.Multi == true,
        _searchable = options.Searchable == true,
        _selection = if options.Multi then {} else nil,
        _disabled = options.Disabled == true,
        _open = false,
        _optionButtons = {},
        _optionConnections = {},
        _searchQuery = "",
    }, Dropdown)
    ui:_InitializeValueComponent(self, options)

    local description = tostring(options.Description or "")
    self._closedHeight = if description == "" then 52 else 66

    local row = ui:_Create("Frame", {
        Name = "Dropdown",
        BackgroundTransparency = 0,
        ClipsDescendants = true,
        LayoutOrder = #section._components + 1,
        Size = UDim2.new(1, 0, 0, self._closedHeight),
        ZIndex = 20,
    }, section._componentContainer)
    self.Instance = row
    self._stroke = ui:_AddStroke(row, 1)
    ui:_AddCorner(row, 7)

    local titleLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, if description == "" then 0 else 7),
        Size = UDim2.new(0.46, -18, 0, if description == "" then self._closedHeight else 20),
        Text = tostring(options.Title),
        TextSize = ui.Config.TextSize,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 21,
    }, row)
    self._titleLabel = titleLabel

    local descriptionLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, 29),
        Size = UDim2.new(0.46, -18, 0, 17),
        Text = description,
        TextSize = ui.Config.TextSize - 2,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = description ~= "",
        ZIndex = 21,
    }, row)
    self._descriptionLabel = descriptionLabel

    local selector = ui:_Create("TextButton", {
        Name = "Selector",
        AnchorPoint = Vector2.new(1, 0.5),
        AutoButtonColor = false,
        BackgroundTransparency = 0,
        Font = ui.Config.Font,
        Position = UDim2.new(1, -10, 0, self._closedHeight / 2),
        Size = UDim2.new(0.52, -10, 0, 34),
        Text = "Select...",
        TextSize = ui.Config.TextSize - 1,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 22,
    }, row)
    ui:_AddCorner(selector, 6)
    self._selector = selector

    ui:_Create("UIPadding", {
        PaddingLeft = UDim.new(0, 10),
        PaddingRight = UDim.new(0, 24),
    }, selector)

    local arrow = ui:_Create("TextLabel", {
        AnchorPoint = Vector2.new(1, 0.5),
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.new(1, -8, 0.5, 0),
        Size = UDim2.fromOffset(14, 18),
        Text = "⌄",
        TextSize = 16,
        ZIndex = 23,
    }, selector)
    self._arrow = arrow

    local panel = ui:_Create("Frame", {
        Name = "OptionsPanel",
        BackgroundTransparency = 0,
        ClipsDescendants = true,
        Position = UDim2.fromOffset(10, self._closedHeight),
        Size = UDim2.new(1, -20, 0, 0),
        Visible = false,
        ZIndex = 30,
    }, row)
    ui:_AddCorner(panel, 6)
    self._panel = panel

    local searchBox = ui:_Create("TextBox", {
        Name = "Search",
        BackgroundTransparency = 0,
        ClearTextOnFocus = false,
        Font = ui.Config.Font,
        PlaceholderText = "Search...",
        Position = UDim2.fromOffset(6, 6),
        Size = UDim2.new(1, -12, 0, 30),
        Text = "",
        TextSize = ui.Config.TextSize - 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = self._searchable,
        ZIndex = 31,
    }, panel)
    ui:_AddCorner(searchBox, 5)
    self._searchBox = searchBox

    ui:_Create("UIPadding", {
        PaddingLeft = UDim.new(0, 9),
        PaddingRight = UDim.new(0, 9),
    }, searchBox)

    local optionList = ui:_Create("ScrollingFrame", {
        Name = "OptionList",
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        CanvasSize = UDim2.new(),
        Position = UDim2.fromOffset(6, if self._searchable then 42 else 6),
        ScrollBarThickness = 2,
        Size = UDim2.new(1, -12, 1, if self._searchable then -48 else -12),
        ZIndex = 31,
    }, panel)
    self._optionList = optionList

    ui:_Create("UIListLayout", {
        Padding = UDim.new(0, OPTION_SPACING),
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, optionList)

    ui:_Connect(self, selector.Activated, function()
        if not self._disabled then
            if self._open then
                self:Close()
            else
                self:Open()
            end
        end
    end)

    ui:_Connect(self, searchBox:GetPropertyChangedSignal("Text"), function()
        self._searchQuery = string.lower(searchBox.Text)
        self:_RebuildOptions()
        if self._open then
            self:_ResizeOpenPanel()
        end
    end)

    local userInputService = ui:_GetUserInputService()
    if userInputService then
        ui:_Connect(self, userInputService.InputBegan, function(input: any)
            if not self._open then
                return
            end

            local inputType = input.UserInputType
            if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
                return
            end

            local position = input.Position
            local absolutePosition = row.AbsolutePosition
            local absoluteSize = row.AbsoluteSize
            local inside = position.X >= absolutePosition.X
                and position.X <= absolutePosition.X + absoluteSize.X
                and position.Y >= absolutePosition.Y
                and position.Y <= absolutePosition.Y + absoluteSize.Y

            if not inside then
                self:Close()
            end
        end)
    end

    ui:_ObserveTheme(self, function()
        self:_ApplyTheme()
    end)

    self:Set(options.Default)
    ui:_BindFlag(self, options.Flag, self:Get())
    self:_RebuildOptions()
    self:_UpdateDisplay()
    return self
end

function Dropdown._FilteredValues(self: any): {any}
    if self._searchQuery == "" then
        return self._values
    end

    local filtered = {}
    for _, value in self._values do
        if string.find(string.lower(tostring(value)), self._searchQuery, 1, true) then
            table.insert(filtered, value)
        end
    end
    return filtered
end

function Dropdown._RebuildOptions(self: any)
    for _, connection in self._optionConnections do
        pcall(function()
            connection:Disconnect()
        end)
    end
    table.clear(self._optionConnections)

    for _, button in self._optionButtons do
        pcall(function()
            button:Destroy()
        end)
    end
    table.clear(self._optionButtons)

    local theme = self._ui:GetTheme()
    for index, value in self:_FilteredValues() do
        local selected = if self._multi then ContainsValue(self._selection, value) else self._selection == value
        local optionButton = self._ui:_Create("TextButton", {
            AutoButtonColor = false,
            BackgroundColor3 = if selected then theme.ElementActive else theme.Element,
            Font = self._ui.Config.Font,
            LayoutOrder = index,
            Size = UDim2.new(1, -4, 0, OPTION_HEIGHT),
            Text = tostring(value),
            TextColor3 = if selected then theme.Accent else theme.Text,
            TextSize = self._ui.Config.TextSize - 1,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 32,
        }, self._optionList)
        self._ui:_AddCorner(optionButton, 5)
        table.insert(self._optionButtons, optionButton)

        local connection = optionButton.Activated:Connect(function()
            if self._multi then
                local updated = self:Get()
                local selectedIndex = table.find(updated, value)
                if selectedIndex then
                    table.remove(updated, selectedIndex)
                else
                    table.insert(updated, value)
                end
                self:Set(updated)
                self:_RebuildOptions()
            else
                self:Set(value)
                self:Close()
            end
        end)
        table.insert(self._optionConnections, connection)
    end
end

function Dropdown._PanelHeight(self: any): number
    local count = math.min(#self:_FilteredValues(), MAX_VISIBLE_OPTIONS)
    local optionsHeight = count * OPTION_HEIGHT + math.max(0, count - 1) * OPTION_SPACING
    return optionsHeight + (if self._searchable then 48 else 12)
end

function Dropdown._ResizeOpenPanel(self: any)
    local panelHeight = self:_PanelHeight()
    self._panel.Size = UDim2.new(1, -20, 0, panelHeight)
    self.Instance.Size = UDim2.new(1, 0, 0, self._closedHeight + panelHeight + 8)
end

function Dropdown._UpdateDisplay(self: any)
    self._selector.Text = SelectionText(self._selection, self._multi)
    self._arrow.Text = if self._open then "⌃" else "⌄"
end

function Dropdown._ApplyTheme(self: any)
    local theme = self._ui:GetTheme()
    self.Instance.BackgroundColor3 = theme.Element
    self._titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
    self._descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
    self._selector.BackgroundColor3 = theme.BackgroundSecondary
    self._selector.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
    self._arrow.TextColor3 = if self._disabled then theme.DisabledText else theme.Accent
    self._panel.BackgroundColor3 = theme.BackgroundSecondary
    self._searchBox.BackgroundColor3 = theme.Element
    self._searchBox.TextColor3 = theme.Text
    self._searchBox.PlaceholderColor3 = theme.DisabledText
    self._optionList.ScrollBarImageColor3 = theme.Accent
    self._stroke.Color = theme.Border
    self:_RebuildOptions()
end

function Dropdown.Set(self: any, value: any)
    local normalized: any

    if self._multi then
        normalized = {}
        if type(value) == "table" then
            for _, availableValue in self._values do
                if table.find(value, availableValue) or value[availableValue] == true then
                    table.insert(normalized, availableValue)
                end
            end
        end
    else
        normalized = if ContainsValue(self._values, value) then value else nil
    end

    if self._ui:_ValuesEqual(self._selection, normalized) then
        self:_UpdateDisplay()
        return
    end

    self._selection = normalized
    self:_UpdateDisplay()
    self:_RebuildOptions()

    local currentValue = self:Get()
    self._ui:_UpdateFlag(self, currentValue)
    self.Changed:Fire(currentValue)
end

function Dropdown.Get(self: any): any
    return if self._multi then self._ui:_CloneValue(self._selection) else self._selection
end

function Dropdown.OnChanged(self: any, callback: any): any?
    return self._ui:_OnChanged(self, callback)
end

function Dropdown.SetValues(self: any, values: any)
    local normalized = {}
    if type(values) == "table" then
        for _, value in values do
            table.insert(normalized, value)
        end
    end

    local previousSelection = self:Get()
    self._values = normalized
    self:Set(previousSelection)
    self:_RebuildOptions()

    if self._open then
        self:_ResizeOpenPanel()
    end
end

function Dropdown.Open(self: any)
    if self._destroyed or self._disabled or self._open then
        return
    end

    self._open = true
    self._panel.Visible = true
    self:_RebuildOptions()
    local panelHeight = self:_PanelHeight()
    self._panel.Size = UDim2.new(1, -20, 0, 0)
    self._ui.Tween:Create(self._panel, "Smooth", {
        Size = UDim2.new(1, -20, 0, panelHeight),
    })
    self._ui.Tween:Create(self.Instance, "Smooth", {
        Size = UDim2.new(1, 0, 0, self._closedHeight + panelHeight + 8),
    })
    self:_UpdateDisplay()
end

function Dropdown.Close(self: any)
    if not self._open then
        return
    end

    self._open = false
    self._panel.Visible = false
    self._ui.Tween:Create(self.Instance, "Smooth", {
        Size = UDim2.new(1, 0, 0, self._closedHeight),
    })
    self:_UpdateDisplay()
end

function Dropdown.SetDisabled(self: any, disabled: any)
    self._disabled = disabled == true
    if self._disabled then
        self:Close()
    end
    self:_ApplyTheme()
end

function Dropdown.Destroy(self: any)
    if self._destroyed then
        return
    end

    for _, connection in self._optionConnections do
        pcall(function()
            connection:Disconnect()
        end)
    end
    table.clear(self._optionConnections)
    table.clear(self._optionButtons)
    local index = table.find(self._section._components, self)
    if index then
        table.remove(self._section._components, index)
    end

    self._ui:_CleanupComponent(self)
end

return Dropdown
]=]

-- Module: ui/components/Keybind.lua (dependencies: none)
__bundle_sources["ui/components/Keybind"] = [=[
--[[
    5AM Hub
    File: ui/components/Keybind.lua

    Rebindable keyboard control supporting Toggle, Hold, and Always modes,
    typing suppression, persistent Enum.KeyCode values, and active callbacks.
]]

local Keybind = {}
Keybind.__index = Keybind

local VALID_MODES = {
    Toggle = true,
    Hold = true,
    Always = true,
}

local function NormalizeMode(mode: any): string
    local text = string.lower(tostring(mode or "Toggle"))

    if text == "hold" then
        return "Hold"
    elseif text == "always" then
        return "Always"
    end

    return "Toggle"
end

local function NormalizeKeyCode(value: any): Enum.KeyCode?
    if typeof(value) == "EnumItem" and value.EnumType == Enum.KeyCode then
        return value
    end

    if type(value) == "string" then
        return (Enum.KeyCode :: any)[value]
    end

    return nil
end

local function KeyCodeText(keyCode: Enum.KeyCode): string
    return if keyCode == Enum.KeyCode.None then "None" else keyCode.Name
end

function Keybind.new(ui: any, section: any, options: any): any
    options = ui:_MergeOptions({
        Title = "Keybind",
        Description = "",
        Default = Enum.KeyCode.None,
        Mode = "Toggle",
        Flag = nil,
        Callback = nil,
        Disabled = false,
    }, options)

    local defaultKey = NormalizeKeyCode(options.Default) or Enum.KeyCode.None
    local mode = NormalizeMode(options.Mode)

    local self = setmetatable({
        _ui = ui,
        _section = section,
        _value = defaultKey,
        _mode = mode,
        _active = mode == "Always",
        _capturing = false,
        _disabled = options.Disabled == true,
        _actionCallback = options.Callback,
    }, Keybind)
    ui:_InitializeValueComponent(self, options, false)
    self.ActiveChanged = ui.Signal.new()

    local description = tostring(options.Description or "")
    local rowHeight = if description == "" then 52 else 66
    local row = ui:_Create("Frame", {
        Name = "Keybind",
        BackgroundTransparency = 0,
        LayoutOrder = #section._components + 1,
        Size = UDim2.new(1, 0, 0, rowHeight),
        ZIndex = 15,
    }, section._componentContainer)
    self.Instance = row
    self._stroke = ui:_AddStroke(row, 1)
    ui:_AddCorner(row, 7)

    local titleLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, if description == "" then 0 else 7),
        Size = UDim2.new(1, -128, 0, if description == "" then rowHeight else 20),
        Text = tostring(options.Title),
        TextSize = ui.Config.TextSize,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 16,
    }, row)
    self._titleLabel = titleLabel

    local descriptionLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, 29),
        Size = UDim2.new(1, -128, 0, 17),
        Text = description,
        TextSize = ui.Config.TextSize - 2,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = description ~= "",
        ZIndex = 16,
    }, row)
    self._descriptionLabel = descriptionLabel

    local keyButton = ui:_Create("TextButton", {
        AnchorPoint = Vector2.new(1, 0.5),
        AutoButtonColor = false,
        BackgroundTransparency = 0,
        Font = ui.Config.Font,
        Position = UDim2.new(1, -10, 0.5, 0),
        Size = UDim2.fromOffset(106, 34),
        Text = KeyCodeText(self._value),
        TextSize = ui.Config.TextSize - 1,
        TextTruncate = Enum.TextTruncate.AtEnd,
        ZIndex = 16,
    }, row)
    ui:_AddCorner(keyButton, 6)
    self._keyButton = keyButton

    local function UpdateKeyText()
        keyButton.Text = if self._capturing then "Press a key..." else KeyCodeText(self._value)
    end
    self._updateKeyText = UpdateKeyText

    ui:_Connect(self, keyButton.Activated, function()
        if not self._disabled then
            self._capturing = true
            UpdateKeyText()
        end
    end)

    local userInputService = ui:_GetUserInputService()
    if userInputService then
        ui:_Connect(self, userInputService.InputBegan, function(input: any, gameProcessed: boolean)
            if self._capturing then
                if input.UserInputType ~= Enum.UserInputType.Keyboard then
                    return
                end

                if input.KeyCode == Enum.KeyCode.Escape then
                    self._capturing = false
                    UpdateKeyText()
                    return
                end

                if input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Delete then
                    self._capturing = false
                    self:Set(Enum.KeyCode.None)
                    return
                end

                if input.KeyCode ~= Enum.KeyCode.Unknown then
                    self._capturing = false
                    self:Set(input.KeyCode)
                end
                return
            end

            if self._disabled or gameProcessed or self._value == Enum.KeyCode.None then
                return
            end

            if userInputService:GetFocusedTextBox() or input.KeyCode ~= self._value then
                return
            end

            if self._mode == "Toggle" then
                self:_SetActive(not self._active)
            elseif self._mode == "Hold" then
                self:_SetActive(true)
            end
        end)

        ui:_Connect(self, userInputService.InputEnded, function(input: any)
            if self._mode == "Hold" and input.KeyCode == self._value then
                self:_SetActive(false)
            end
        end)
    end

    ui:_ObserveTheme(self, function(theme: any)
        row.BackgroundColor3 = theme.Element
        titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
        descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
        keyButton.BackgroundColor3 = if self._active then theme.ElementActive else theme.BackgroundSecondary
        keyButton.TextColor3 = if self._disabled then theme.DisabledText else theme.Accent
        self._stroke.Color = theme.Border
    end)

    ui:_BindFlag(self, options.Flag, self._value)
    return self
end

function Keybind._SetActive(self: any, active: boolean)
    if self._mode == "Always" then
        active = true
    end

    if self._active == active then
        return
    end

    self._active = active
    local theme = self._ui:GetTheme()
    self._keyButton.BackgroundColor3 = if active then theme.ElementActive else theme.BackgroundSecondary

    self._ui:_SafeCall(self._actionCallback, active)
    self.ActiveChanged:Fire(active)
end

function Keybind.Set(self: any, value: any)
    local normalized = NormalizeKeyCode(value)
    if not normalized then
        return
    end

    if self._value == normalized then
        self._updateKeyText()
        return
    end

    self._value = normalized
    self._updateKeyText()
    self._ui:_UpdateFlag(self, self._value)
    self.Changed:Fire(self._value)

    if normalized == Enum.KeyCode.None and self._mode ~= "Always" then
        self:_SetActive(false)
    end
end

function Keybind.Get(self: any): Enum.KeyCode
    return self._value
end

function Keybind.OnChanged(self: any, callback: any): any?
    return self._ui:_OnChanged(self, callback)
end

function Keybind.OnActivated(self: any, callback: any): any?
    if self._destroyed or type(callback) ~= "function" then
        return nil
    end

    local connection = self.ActiveChanged:Connect(function(active: boolean)
        self._ui:_SafeCall(callback, active)
    end)
    return self._ui:_TrackConnection(self, connection)
end

function Keybind.SetMode(self: any, mode: any)
    local normalized = NormalizeMode(mode)
    if not VALID_MODES[normalized] or self._mode == normalized then
        return
    end

    self._mode = normalized
    self:_SetActive(normalized == "Always")
end

function Keybind.IsActive(self: any): boolean
    return self._active
end

function Keybind.SetDisabled(self: any, disabled: any)
    self._disabled = disabled == true
    if self._disabled then
        self._capturing = false
        self._updateKeyText()
        if self._mode ~= "Always" then
            self:_SetActive(false)
        end
    end

    local theme = self._ui:GetTheme()
    self._titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
    self._descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
    self._keyButton.TextColor3 = if self._disabled then theme.DisabledText else theme.Accent
end

function Keybind.Destroy(self: any)
    if self._destroyed then
        return
    end

    self._capturing = false
    self._active = false
    self.ActiveChanged:Disconnect()

    local index = table.find(self._section._components, self)
    if index then
        table.remove(self._section._components, index)
    end

    self._ui:_CleanupComponent(self)
end

return Keybind
]=]

