__bundle_sources["ui/components/Slider"] = [=[
--[[
    5AM Hub
    File: ui/components/Slider.lua

    Mouse and touch numeric slider with clamping, increment rounding,
    animation, flag persistence, and safe invalid-range handling.
]]

local Slider = {}
Slider.__index = Slider

local function Clamp(value: number, minimum: number, maximum: number): number
    return math.max(minimum, math.min(maximum, value))
end

local function NormalizeRange(minimum: any, maximum: any): (number, number)
    local normalizedMin = tonumber(minimum) or 0
    local normalizedMax = tonumber(maximum) or 100

    if normalizedMax < normalizedMin then
        normalizedMin, normalizedMax = normalizedMax, normalizedMin
    end

    return normalizedMin, normalizedMax
end

local function RoundToIncrement(value: number, minimum: number, increment: number): number
    if increment <= 0 then
        return value
    end

    return minimum + math.floor(((value - minimum) / increment) + 0.5) * increment
end

local function DecimalPlaces(increment: number): number
    local text = string.format("%.6f", increment)
    text = string.gsub(text, "0+$", "")
    local decimals = string.match(text, "%.(%d+)$")
    return if decimals then #decimals else 0
end

function Slider.new(ui: any, section: any, options: any): any
    options = ui:_MergeOptions({
        Title = "Slider",
        Description = "",
        Min = 0,
        Max = 100,
        Default = 50,
        Increment = 1,
        Suffix = "",
        Flag = nil,
        Callback = nil,
        Disabled = false,
    }, options)

    local minimum, maximum = NormalizeRange(options.Min, options.Max)
    local increment = math.abs(tonumber(options.Increment) or 1)
    if increment == 0 then
        increment = 1
    end

    local defaultValue = Clamp(tonumber(options.Default) or minimum, minimum, maximum)
    defaultValue = Clamp(RoundToIncrement(defaultValue, minimum, increment), minimum, maximum)

    local self = setmetatable({
        _ui = ui,
        _section = section,
        _min = minimum,
        _max = maximum,
        _increment = increment,
        _suffix = tostring(options.Suffix or ""),
        _value = defaultValue,
        _disabled = options.Disabled == true,
        _dragging = false,
        _dragInput = nil,
    }, Slider)
    ui:_InitializeValueComponent(self, options)

    local description = tostring(options.Description or "")
    local row = ui:_Create("Frame", {
        Name = "Slider",
        BackgroundTransparency = 0,
        LayoutOrder = #section._components + 1,
        Size = UDim2.new(1, 0, 0, if description == "" then 66 else 78),
        ZIndex = 15,
    }, section._componentContainer)
    self.Instance = row
    self._stroke = ui:_AddStroke(row, 1)
    ui:_AddCorner(row, 7)

    local titleLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, 7),
        Size = UDim2.new(1, -110, 0, 20),
        Text = tostring(options.Title),
        TextSize = ui.Config.TextSize,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 16,
    }, row)
    self._titleLabel = titleLabel

    local descriptionLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, 28),
        Size = UDim2.new(1, -24, 0, 16),
        Text = description,
        TextSize = ui.Config.TextSize - 2,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = description ~= "",
        ZIndex = 16,
    }, row)
    self._descriptionLabel = descriptionLabel

    local valueLabel = ui:_Create("TextLabel", {
        AnchorPoint = Vector2.new(1, 0),
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.new(1, -12, 0, 7),
        Size = UDim2.fromOffset(92, 20),
        Text = "",
        TextSize = ui.Config.TextSize,
        TextXAlignment = Enum.TextXAlignment.Right,
        ZIndex = 16,
    }, row)
    self._valueLabel = valueLabel

    local trackY = if description == "" then 44 else 56
    local track = ui:_Create("Frame", {
        Name = "Track",
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 0,
        Position = UDim2.new(0, 12, 0, trackY),
        Size = UDim2.new(1, -24, 0, 6),
        ZIndex = 16,
    }, row)
    ui:_AddCorner(track, 3)
    self._track = track

    local fill = ui:_Create("Frame", {
        Name = "Fill",
        BackgroundTransparency = 0,
        Size = UDim2.fromScale(0, 1),
        ZIndex = 17,
    }, track)
    ui:_AddCorner(fill, 3)
    self._fill = fill

    local hitbox = ui:_Create("TextButton", {
        Name = "Hitbox",
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 0, 0.5, 0),
        Size = UDim2.new(1, 0, 0, 24),
        Text = "",
        ZIndex = 18,
    }, track)

    local function UpdateFromInput(input: any)
        if self._disabled or self._destroyed or track.AbsoluteSize.X <= 0 then
            return
        end

        local relativeX = input.Position.X - track.AbsolutePosition.X
        local ratio = Clamp(relativeX / track.AbsoluteSize.X, 0, 1)
        self:Set(self._min + (self._max - self._min) * ratio)
    end

    ui:_Connect(self, hitbox.InputBegan, function(input: any)
        local inputType = input.UserInputType
        if self._disabled or (inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch) then
            return
        end

        self._dragging = true
        self._dragInput = input
        UpdateFromInput(input)
    end)

    local userInputService = ui:_GetUserInputService()
    if userInputService then
        ui:_Connect(self, userInputService.InputChanged, function(input: any)
            if not self._dragging or not self._dragInput then
                return
            end

            local activeType = self._dragInput.UserInputType
            if (activeType == Enum.UserInputType.Touch and input == self._dragInput)
                or (activeType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement)
            then
                UpdateFromInput(input)
            end
        end)

        ui:_Connect(self, userInputService.InputEnded, function(input: any)
            if input == self._dragInput or (
                self._dragInput
                and self._dragInput.UserInputType == Enum.UserInputType.MouseButton1
                and input.UserInputType == Enum.UserInputType.MouseButton1
            ) then
                self._dragging = false
                self._dragInput = nil
            end
        end)
    end

    ui:_ObserveTheme(self, function(theme: any)
        row.BackgroundColor3 = theme.Element
        titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
        descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
        valueLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Accent
        track.BackgroundColor3 = theme.Border
        fill.BackgroundColor3 = theme.Accent
        self._stroke.Color = theme.Border
    end)

    ui:_BindFlag(self, options.Flag, self._value)
    self:Set(self._value)
    return self
end

function Slider._UpdateVisual(self: any)
    local range = self._max - self._min
    local ratio = if range == 0 then 0 else Clamp((self._value - self._min) / range, 0, 1)
    local decimals = DecimalPlaces(self._increment)
    self._valueLabel.Text = string.format("%." .. tostring(decimals) .. "f%s", self._value, self._suffix)
    self._ui.Tween:Create(self._fill, "Smooth", {
        Size = UDim2.fromScale(ratio, 1),
    })
end

function Slider.Set(self: any, value: any)
    local numericValue = tonumber(value)
    if not numericValue then
        return
    end

    local normalized = Clamp(numericValue, self._min, self._max)
    normalized = Clamp(RoundToIncrement(normalized, self._min, self._increment), self._min, self._max)

    if self._value == normalized then
        self:_UpdateVisual()
        return
    end

    self._value = normalized
    self:_UpdateVisual()
    self._ui:_UpdateFlag(self, self._value)
    self.Changed:Fire(self._value)
end

function Slider.Get(self: any): number
    return self._value
end

function Slider.OnChanged(self: any, callback: any): any?
    return self._ui:_OnChanged(self, callback)
end

function Slider.SetMin(self: any, value: any)
    local minimum = tonumber(value)
    if not minimum then
        return
    end

    self._min = minimum
    if self._max < self._min then
        self._max = self._min
    end
    self:Set(self._value)
end

function Slider.SetMax(self: any, value: any)
    local maximum = tonumber(value)
    if not maximum then
        return
    end

    self._max = maximum
    if self._min > self._max then
        self._min = self._max
    end
    self:Set(self._value)
end

function Slider.SetDisabled(self: any, disabled: any)
    self._disabled = disabled == true
    local theme = self._ui:GetTheme()
    self._titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
    self._descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
    self._valueLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Accent
end

function Slider.Destroy(self: any)
    if self._destroyed then
        return
    end

    self._dragging = false
    self._dragInput = nil

    local index = table.find(self._section._components, self)
    if index then
        table.remove(self._section._components, index)
    end

    self._ui:_CleanupComponent(self)
end

return Slider
]=]

-- Module: ui/components/Tab.lua (dependencies: none)
__bundle_sources["ui/components/Tab"] = [=[
--[[
    5AM Hub
    File: ui/components/Tab.lua

    Window-owned navigation tab and scrolling section container.
]]

local Tab = {}
Tab.__index = Tab

local function FormatNavigationText(icon: any, title: string): string
    local iconText = if icon == nil then "" else tostring(icon)
    return if iconText == "" then title else string.format("%s   %s", iconText, title)
end

function Tab.new(ui: any, window: any, options: any): any
    local self = setmetatable({
        _ui = ui,
        _window = window,
        _connections = {},
        _destroyed = false,
        _sections = {},
        _selected = false,
        _visible = options.Visible ~= false,
        _title = tostring(options.Title or "Tab"),
        _icon = options.Icon,
    }, Tab)

    local navigationButton = ui:_Create("TextButton", {
        Name = "TabButton",
        AutoButtonColor = false,
        BackgroundTransparency = 0,
        Font = ui.Config.Font,
        LayoutOrder = #window._tabs + 1,
        Size = UDim2.new(1, 0, 0, 36),
        Text = FormatNavigationText(self._icon, self._title),
        TextSize = ui.Config.TextSize,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = self._visible,
        ZIndex = 13,
    }, window._navigation)
    ui:_AddCorner(navigationButton, 7)
    self._navigationButton = navigationButton

    ui:_Create("UIPadding", {
        PaddingLeft = UDim.new(0, 12),
        PaddingRight = UDim.new(0, 8),
    }, navigationButton)

    local content = ui:_Create("ScrollingFrame", {
        Name = "TabContent",
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        CanvasSize = UDim2.new(),
        ScrollBarThickness = 3,
        Size = UDim2.fromScale(1, 1),
        Visible = false,
        ZIndex = 12,
    }, window._content)
    self.Instance = content

    ui:_Create("UIPadding", {
        PaddingBottom = UDim.new(0, 16),
        PaddingLeft = UDim.new(0, 16),
        PaddingRight = UDim.new(0, 16),
        PaddingTop = UDim.new(0, 16),
    }, content)

    ui:_Create("UIListLayout", {
        Padding = UDim.new(0, 12),
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, content)

    ui:_Connect(self, navigationButton.Activated, function()
        self:Select()
    end)

    ui:_ObserveTheme(self, function(theme: any)
        navigationButton.BackgroundColor3 = if self._selected then theme.Accent else theme.Element
        navigationButton.TextColor3 = if self._selected then theme.Text else theme.SubText
        content.ScrollBarImageColor3 = theme.Accent
    end)

    return self
end

function Tab.AddSection(self: any, titleOrOptions: any): any
    if self._destroyed then
        return nil
    end

    local options = if type(titleOrOptions) == "table" then self._ui:_MergeOptions({}, titleOrOptions) else {
        Title = tostring(titleOrOptions or ""),
    }

    local section = self._ui.Components.Section.new(self._ui, self, options)
    table.insert(self._sections, section)
    return section
end

function Tab.SetTitle(self: any, title: any)
    self._title = tostring(title or "")
    self._navigationButton.Text = FormatNavigationText(self._icon, self._title)
end

function Tab.SetIcon(self: any, icon: any)
    self._icon = icon
    self._navigationButton.Text = FormatNavigationText(self._icon, self._title)
end

function Tab.Select(self: any): boolean
    return self._window:SelectTab(self)
end

function Tab._SetSelected(self: any, selected: boolean)
    self._selected = selected
    self.Instance.Visible = selected and self._visible

    local theme = self._ui:GetTheme()
    self._navigationButton.BackgroundColor3 = if selected then theme.Accent else theme.Element
    self._navigationButton.TextColor3 = if selected then theme.Text else theme.SubText
end

function Tab.SetVisible(self: any, visible: any)
    self._visible = visible == true
    self._navigationButton.Visible = self._visible
    self.Instance.Visible = self._visible and self._selected

    if not self._visible and self._selected then
        for _, sibling in self._window._tabs do
            if sibling ~= self and sibling._visible then
                sibling:Select()
                break
            end
        end
    end
end

function Tab.Destroy(self: any)
    if self._destroyed then
        return
    end

    local wasSelected = self._selected
    local sections = table.clone(self._sections)
    for _, section in sections do
        section:Destroy()
    end
    table.clear(self._sections)

    local tabIndex = table.find(self._window._tabs, self)
    if tabIndex then
        table.remove(self._window._tabs, tabIndex)
    end

    pcall(function()
        self._navigationButton:Destroy()
    end)

    self._ui:_CleanupComponent(self)

    if wasSelected then
        self._window._selectedTab = nil
        for _, sibling in self._window._tabs do
            if sibling._visible then
                self._window:SelectTab(sibling)
                break
            end
        end
    end
end

return Tab
]=]

-- Module: ui/components/Textbox.lua (dependencies: none)
__bundle_sources["ui/components/Textbox"] = [=[
--[[
    5AM Hub
    File: ui/components/Textbox.lua

    Persistent text input with finished/live callbacks, numeric filtering,
    cursor-aware normalization, placeholders, and length limits.
]]

local Textbox = {}
Textbox.__index = Textbox

local function NormalizeNumericText(text: string): string
    local output = ""
    local hasDecimal = false

    for index = 1, #text do
        local character = string.sub(text, index, index)

        if string.match(character, "%d") then
            output ..= character
        elseif character == "-" and #output == 0 then
            output ..= character
        elseif character == "." and not hasDecimal then
            output ..= character
            hasDecimal = true
        end
    end

    return output
end

local function NormalizeText(value: any, numeric: boolean, maximumLength: number?): string
    local text = tostring(value or "")

    if numeric then
        text = NormalizeNumericText(text)
    end

    if maximumLength and maximumLength >= 0 and #text > maximumLength then
        text = string.sub(text, 1, maximumLength)
    end

    return text
end

function Textbox.new(ui: any, section: any, options: any): any
    options = ui:_MergeOptions({
        Title = "Textbox",
        Description = "",
        Default = "",
        Placeholder = "",
        Numeric = false,
        ClearOnFocus = false,
        Finished = true,
        MaxLength = nil,
        Flag = nil,
        Callback = nil,
        Disabled = false,
    }, options)

    local maximumLength = tonumber(options.MaxLength)
    if maximumLength then
        maximumLength = math.max(0, math.floor(maximumLength))
    end

    local self = setmetatable({
        _ui = ui,
        _section = section,
        _numeric = options.Numeric == true,
        _finished = options.Finished ~= false,
        _maximumLength = maximumLength,
        _disabled = options.Disabled == true,
        _updatingText = false,
        _value = NormalizeText(options.Default, options.Numeric == true, maximumLength),
    }, Textbox)
    ui:_InitializeValueComponent(self, options)

    local description = tostring(options.Description or "")
    local rowHeight = if description == "" then 52 else 66
    local row = ui:_Create("Frame", {
        Name = "Textbox",
        BackgroundTransparency = 0,
        LayoutOrder = #section._components + 1,
        Size = UDim2.new(1, 0, 0, rowHeight),
        ZIndex = 15,
    }, section._componentContainer)
    self.Instance = row
    self._stroke = ui:_AddStroke(row, 1)
    ui:_AddCorner(row, 7)

    local titleLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, if description == "" then 0 else 7),
        Size = UDim2.new(0.44, -16, 0, if description == "" then rowHeight else 20),
        Text = tostring(options.Title),
        TextSize = ui.Config.TextSize,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 16,
    }, row)
    self._titleLabel = titleLabel

    local descriptionLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, 29),
        Size = UDim2.new(0.44, -16, 0, 17),
        Text = description,
        TextSize = ui.Config.TextSize - 2,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = description ~= "",
        ZIndex = 16,
    }, row)
    self._descriptionLabel = descriptionLabel

    local textInput = ui:_Create("TextBox", {
        Name = "Input",
        AnchorPoint = Vector2.new(1, 0.5),
        BackgroundTransparency = 0,
        ClearTextOnFocus = options.ClearOnFocus == true,
        Font = ui.Config.Font,
        MultiLine = false,
        PlaceholderText = tostring(options.Placeholder or ""),
        Position = UDim2.new(1, -10, 0.5, 0),
        Size = UDim2.new(0.54, -10, 0, 34),
        Text = self._value,
        TextEditable = not self._disabled,
        TextSize = ui.Config.TextSize - 1,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 16,
    }, row)
    ui:_AddCorner(textInput, 6)
    self._textInput = textInput

    ui:_Create("UIPadding", {
        PaddingLeft = UDim.new(0, 10),
        PaddingRight = UDim.new(0, 10),
    }, textInput)

    local function NormalizeVisibleText()
        if self._updatingText then
            return
        end

        local currentText = textInput.Text
        local normalized = NormalizeText(currentText, self._numeric, self._maximumLength)

        if normalized ~= currentText then
            local cursorPosition = textInput.CursorPosition
            self._updatingText = true
            textInput.Text = normalized
            textInput.CursorPosition = math.min(cursorPosition, #normalized + 1)
            self._updatingText = false
        end

        if not self._finished then
            self:Set(normalized)
        end
    end

    ui:_Connect(self, textInput:GetPropertyChangedSignal("Text"), NormalizeVisibleText)
    ui:_Connect(self, textInput.FocusLost, function()
        self:Set(textInput.Text)
    end)

    ui:_ObserveTheme(self, function(theme: any)
        row.BackgroundColor3 = theme.Element
        titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
        descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
        textInput.BackgroundColor3 = theme.BackgroundSecondary
        textInput.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
        textInput.PlaceholderColor3 = theme.DisabledText
        self._stroke.Color = theme.Border
    end)

    ui:_BindFlag(self, options.Flag, self._value)
    return self
end

function Textbox.Set(self: any, value: any)
    local normalized = NormalizeText(value, self._numeric, self._maximumLength)
    local changed = self._value ~= normalized
    self._value = normalized

    if self._textInput.Text ~= normalized then
        local hadFocus = self._textInput:IsFocused()
        local cursorPosition = self._textInput.CursorPosition
        self._updatingText = true
        self._textInput.Text = normalized
        if hadFocus then
            self._textInput.CursorPosition = math.min(cursorPosition, #normalized + 1)
        end
        self._updatingText = false
    end

    if changed then
        self._ui:_UpdateFlag(self, self._value)
        self.Changed:Fire(self._value)
    end
end

function Textbox.Get(self: any): string
    return self._value
end

function Textbox.OnChanged(self: any, callback: any): any?
    return self._ui:_OnChanged(self, callback)
end

function Textbox.SetPlaceholder(self: any, text: any)
    self._textInput.PlaceholderText = tostring(text or "")
end

function Textbox.SetDisabled(self: any, disabled: any)
    self._disabled = disabled == true
    self._textInput.TextEditable = not self._disabled
    self._textInput.Active = not self._disabled

    local theme = self._ui:GetTheme()
    self._titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
    self._descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
    self._textInput.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
end

function Textbox.Focus(self: any)
    if not self._disabled and not self._destroyed then
        self._textInput:CaptureFocus()
    end
end

function Textbox.Destroy(self: any)
    if self._destroyed then
        return
    end

    if self._textInput:IsFocused() then
        self._textInput:ReleaseFocus()
    end

    local index = table.find(self._section._components, self)
    if index then
        table.remove(self._section._components, index)
    end

    self._ui:_CleanupComponent(self)
end

return Textbox
]=]

-- Module: ui/components/Toggle.lua (dependencies: none)
__bundle_sources["ui/components/Toggle"] = [=[
--[[
    5AM Hub
    File: ui/components/Toggle.lua

    Persistent boolean switch with animated Fluent-style visual states.
]]

local Toggle = {}
Toggle.__index = Toggle

function Toggle.new(ui: any, section: any, options: any): any
    options = ui:_MergeOptions({
        Title = "Toggle",
        Description = "",
        Default = false,
        Flag = nil,
        Callback = nil,
        Disabled = false,
    }, options)

    local self = setmetatable({
        _ui = ui,
        _section = section,
        _value = options.Default == true,
        _disabled = options.Disabled == true,
    }, Toggle)
    ui:_InitializeValueComponent(self, options)

    local description = tostring(options.Description or "")
    local rowHeight = if description == "" then 44 else 58
    local row = ui:_Create("TextButton", {
        Name = "Toggle",
        AutoButtonColor = false,
        BackgroundTransparency = 0,
        LayoutOrder = #section._components + 1,
        Size = UDim2.new(1, 0, 0, rowHeight),
        Text = "",
        ZIndex = 15,
    }, section._componentContainer)
    self.Instance = row
    self._stroke = ui:_AddStroke(row, 1)
    ui:_AddCorner(row, 7)

    local titleLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, if description == "" then 0 else 8),
        Size = UDim2.new(1, -70, 0, if description == "" then rowHeight else 20),
        Text = tostring(options.Title),
        TextSize = ui.Config.TextSize,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 16,
    }, row)
    self._titleLabel = titleLabel

    local descriptionLabel = ui:_Create("TextLabel", {
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(12, 29),
        Size = UDim2.new(1, -70, 0, 17),
        Text = description,
        TextSize = ui.Config.TextSize - 2,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = description ~= "",
        ZIndex = 16,
    }, row)
    self._descriptionLabel = descriptionLabel

    local switch = ui:_Create("Frame", {
        AnchorPoint = Vector2.new(1, 0.5),
        BackgroundTransparency = 0,
        Position = UDim2.new(1, -12, 0.5, 0),
        Size = UDim2.fromOffset(42, 22),
        ZIndex = 16,
    }, row)
    ui:_AddCorner(switch, 11)
    self._switch = switch

    local knob = ui:_Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = ui:GetTheme().Text,
        Position = UDim2.new(0, 11, 0.5, 0),
        Size = UDim2.fromOffset(16, 16),
        ZIndex = 17,
    }, switch)
    ui:_AddCorner(knob, 8)
    self._knob = knob

    local function ApplyVisualState()
        if self._destroyed then
            return
        end

        local theme = ui:GetTheme()
        local switchColor = if self._value then theme.Accent else theme.Border
        if self._disabled then
            switchColor = theme.Divider
        end

        ui.Tween:Create(switch, "Smooth", { BackgroundColor3 = switchColor })
        ui.Tween:Create(knob, "Smooth", {
            Position = UDim2.new(0, if self._value then 31 else 11, 0.5, 0),
        })
        row.BackgroundColor3 = theme.Element
        titleLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.Text
        descriptionLabel.TextColor3 = if self._disabled then theme.DisabledText else theme.SubText
        knob.BackgroundColor3 = theme.Text
        self._stroke.Color = theme.Border
    end
    self._applyVisualState = ApplyVisualState

    ui:_Connect(self, row.Activated, function()
        if not self._disabled then
            self:Set(not self._value)
        end
    end)

    ui:_ObserveTheme(self, function()
        ApplyVisualState()
    end)

    ui:_BindFlag(self, options.Flag, self._value)
    ApplyVisualState()
    return self
end

function Toggle.Set(self: any, value: any)
    local normalized = value == true
    if self._value == normalized then
        self._applyVisualState()
        return
    end

    self._value = normalized
    self._applyVisualState()
    self._ui:_UpdateFlag(self, self._value)
    self.Changed:Fire(self._value)
end

function Toggle.Get(self: any): boolean
    return self._value
end

function Toggle.OnChanged(self: any, callback: any): any?
    return self._ui:_OnChanged(self, callback)
end

function Toggle.SetDisabled(self: any, disabled: any)
    self._disabled = disabled == true
    self._applyVisualState()
end

function Toggle.Destroy(self: any)
    if self._destroyed then
        return
    end

    local index = table.find(self._section._components, self)
    if index then
        table.remove(self._section._components, index)
    end

    self._ui:_CleanupComponent(self)
end

return Toggle
]=]

-- Module: ui/components/Window.lua (dependencies: none)
__bundle_sources["ui/components/Window"] = [=[
--[[
    5AM Hub
    File: ui/components/Window.lua

    Top-level Fluent-style window with navigation, draggable header,
    visibility, minimization, sizing, theming, and deterministic cleanup.
]]

local Window = {}
Window.__index = Window

local HEADER_HEIGHT = 56
local NAVIGATION_WIDTH = 158

local function NormalizeSize(size: any, minimumSize: Vector2, fallback: UDim2): UDim2
    if typeof(size) == "Vector2" then
        return UDim2.fromOffset(
            math.max(size.X, minimumSize.X),
            math.max(size.Y, minimumSize.Y)
        )
    end

    if typeof(size) ~= "UDim2" then
        size = fallback
    end

    local xOffset = size.X.Offset
    local yOffset = size.Y.Offset

    if size.X.Scale == 0 then
        xOffset = math.max(xOffset, minimumSize.X)
    end

    if size.Y.Scale == 0 then
        yOffset = math.max(yOffset, minimumSize.Y)
    end

    return UDim2.new(size.X.Scale, xOffset, size.Y.Scale, yOffset)
end

function Window.new(ui: any, options: any): any
    local self = setmetatable({
        _ui = ui,
        _connections = {},
        _destroyed = false,
        _tabs = {},
        _selectedTab = nil,
        _visible = true,
        _minimized = false,
        _restoreSize = nil,
        _minimumSize = if typeof(options.MinSize) == "Vector2" then options.MinSize else ui.Config.MinSize,
        _title = tostring(options.Title or ui.Config.Title),
        _subTitle = tostring(options.SubTitle or ui.Config.SubTitle),
    }, Window)

    local rootGui = ui:_EnsureRootGui()
    local windowFrame = ui:_Create("Frame", {
        Name = "Window",
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundTransparency = if options.Transparency then 0.08 else 0,
        ClipsDescendants = true,
        Position = UDim2.fromScale(0.5, 0.5),
        Size = NormalizeSize(options.Size, self._minimumSize, ui.Config.Size),
        Visible = true,
        ZIndex = 10,
    }, rootGui)
    self.Instance = windowFrame
    self._stroke = ui:_AddStroke(windowFrame, 1)
    ui:_AddCorner(windowFrame, ui.Config.CornerRadius)
    self._sizeConstraint = ui:_Create("UISizeConstraint", {
        MinSize = self._minimumSize,
        MaxSize = Vector2.new(10000, 10000),
    }, windowFrame)

    local header = ui:_Create("Frame", {
        Name = "Header",
        BackgroundTransparency = 0,
        BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, HEADER_HEIGHT),
        ZIndex = 11,
    }, windowFrame)
    self._header = header

    local titleLabel = ui:_Create("TextLabel", {
        Name = "Title",
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(18, 8),
        Size = UDim2.new(1, -78, 0, 22),
        Text = self._title,
        TextSize = ui.Config.TextSize + 2,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 12,
    }, header)
    self._titleLabel = titleLabel

    local subTitleLabel = ui:_Create("TextLabel", {
        Name = "SubTitle",
        BackgroundTransparency = 1,
        Font = ui.Config.Font,
        Position = UDim2.fromOffset(18, 30),
        Size = UDim2.new(1, -78, 0, 17),
        Text = self._subTitle,
        TextSize = ui.Config.TextSize - 2,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        Visible = self._subTitle ~= "",
        ZIndex = 12,
    }, header)
    self._subTitleLabel = subTitleLabel

    local minimizeButton = ui:_Create("TextButton", {
        Name = "Minimize",
        AnchorPoint = Vector2.new(1, 0.5),
        AutoButtonColor = false,
        BackgroundTransparency = 0,
        Font = ui.Config.Font,
        Position = UDim2.new(1, -12, 0.5, 0),
        Size = UDim2.fromOffset(32, 32),
        Text = "—",
        TextSize = 18,
        Visible = options.MinimizeEnabled ~= false,
        ZIndex = 13,
    }, header)
    ui:_AddCorner(minimizeButton, 7)
    self._minimizeButton = minimizeButton

    local divider = ui:_Create("Frame", {
        Name = "HeaderDivider",
        BorderSizePixel = 0,
        Position = UDim2.new(0, 0, 1, -1),
        Size = UDim2.new(1, 0, 0, 1),
        ZIndex = 12,
    }, header)
    self._headerDivider = divider

    local body = ui:_Create("Frame", {
        Name = "Body",
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(0, HEADER_HEIGHT),
        Size = UDim2.new(1, 0, 1, -HEADER_HEIGHT),
        ZIndex = 11,
    }, windowFrame)
    self._body = body

    local navigation = ui:_Create("ScrollingFrame", {
        Name = "Navigation",
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 0,
        BorderSizePixel = 0,
        CanvasSize = UDim2.new(),
        ScrollBarThickness = 2,
        Size = UDim2.new(0, NAVIGATION_WIDTH, 1, 0),
        ZIndex = 11,
    }, body)
    self._navigation = navigation

    ui:_Create("UIPadding", {
        PaddingBottom = UDim.new(0, 12),
        PaddingLeft = UDim.new(0, 10),
        PaddingRight = UDim.new(0, 10),
        PaddingTop = UDim.new(0, 12),
    }, navigation)

    ui:_Create("UIListLayout", {
        Padding = UDim.new(0, 6),
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, navigation)

    local navigationDivider = ui:_Create("Frame", {
        Name = "NavigationDivider",
        BorderSizePixel = 0,
        Position = UDim2.new(0, NAVIGATION_WIDTH - 1, 0, 0),
        Size = UDim2.new(0, 1, 1, 0),
        ZIndex = 12,
    }, body)
    self._navigationDivider = navigationDivider

    local content = ui:_Create("Frame", {
        Name = "Content",
        BackgroundTransparency = 1,
        ClipsDescendants = true,
        Position = UDim2.fromOffset(NAVIGATION_WIDTH, 0),
        Size = UDim2.new(1, -NAVIGATION_WIDTH, 1, 0),
        ZIndex = 11,
    }, body)
    self._content = content

    self._dragController = ui.Drag:Enable(windowFrame, header)

    ui:_Connect(self, minimizeButton.Activated, function()
        if self._minimized then
            self:Restore()
        else
            self:Minimize()
        end
    end)

    local userInputService = ui:_GetUserInputService()
    if userInputService and options.ToggleKey ~= Enum.KeyCode.None then
        ui:_Connect(self, userInputService.InputBegan, function(input: any, gameProcessed: boolean)
            if gameProcessed or input.KeyCode ~= options.ToggleKey then
                return
            end

            if userInputService:GetFocusedTextBox() then
                return
            end

            self:SetVisible(not self._visible)
        end)
    end

    ui:_ObserveTheme(self, function(theme: any)
        windowFrame.BackgroundColor3 = theme.Background
        header.BackgroundColor3 = theme.BackgroundSecondary
        navigation.BackgroundColor3 = theme.BackgroundSecondary
        titleLabel.TextColor3 = theme.Text
        subTitleLabel.TextColor3 = theme.SubText
        minimizeButton.BackgroundColor3 = theme.Element
        minimizeButton.TextColor3 = theme.Text
        divider.BackgroundColor3 = theme.Divider
        navigationDivider.BackgroundColor3 = theme.Divider
        self._stroke.Color = theme.Border
        navigation.ScrollBarImageColor3 = theme.Accent
    end)

    return self
end

function Window.AddTab(self: any, options: any): any
    if self._destroyed then
        return nil
    end

    local normalized = if type(options) == "table" then self._ui:_MergeOptions({}, options) else {
        Title = tostring(options or "Tab"),
    }
    normalized.Title = normalized.Title or "Tab"

    local tab = self._ui.Components.Tab.new(self._ui, self, normalized)
    table.insert(self._tabs, tab)

    if not self._selectedTab then
        self:SelectTab(tab)
    else
        tab:_SetSelected(false)
    end

    return tab
end

function Window.SelectTab(self: any, tab: any): boolean
    if self._destroyed or not table.find(self._tabs, tab) then
        return false
    end

    self._selectedTab = tab

    for _, ownedTab in self._tabs do
        ownedTab:_SetSelected(ownedTab == tab)
    end

    return true
end

function Window.SetTitle(self: any, title: any)
    self._title = tostring(title or "")
    self._titleLabel.Text = self._title
end

function Window.SetSubTitle(self: any, subTitle: any)
    self._subTitle = tostring(subTitle or "")
    self._subTitleLabel.Text = self._subTitle
    self._subTitleLabel.Visible = self._subTitle ~= ""
end

function Window.SetTheme(self: any, themeName: string): boolean
    return self._ui:SetTheme(themeName)
end

function Window.SetVisible(self: any, visible: any)
    self._visible = visible == true
    self.Instance.Visible = self._visible
end

function Window.SetSize(self: any, size: any)
    local normalizedSize = NormalizeSize(size, self._minimumSize, self._ui.Config.Size)

    if self._minimized then
        self._restoreSize = normalizedSize
    else
        self.Instance.Size = normalizedSize
    end
end

function Window.Minimize(self: any)
    if self._destroyed or self._minimized or not self._minimizeButton.Visible then
        return
    end

    self._minimized = true
    self._restoreSize = self.Instance.Size
    self._sizeConstraint.MinSize = Vector2.new(self._minimumSize.X, HEADER_HEIGHT)
    self._body.Visible = false
    self._minimizeButton.Text = "+"

    self._ui.Tween:Create(self.Instance, "Smooth", {
        Size = UDim2.new(self.Instance.Size.X.Scale, self.Instance.Size.X.Offset, 0, HEADER_HEIGHT),
    })
end

function Window.Restore(self: any)
    if self._destroyed or not self._minimized then
        return
    end

    self._minimized = false
    self._sizeConstraint.MinSize = self._minimumSize
    self._body.Visible = true
    self._minimizeButton.Text = "—"

    self._ui.Tween:Create(self.Instance, "Smooth", {
        Size = self._restoreSize or self._ui.Config.Size,
    })
end

function Window.Destroy(self: any)
    if self._destroyed then
        return
    end

    local tabs = table.clone(self._tabs)
    for _, tab in tabs do
        tab:Destroy()
    end
    table.clear(self._tabs)

    if self._dragController then
        self._dragController:Disconnect()
        self._dragController = nil
    end

    self._ui:_RemoveWindow(self)
    self._ui:_CleanupComponent(self)
end

return Window
]=]

