__bundle_require = function(moduleName)
    if __bundle_loaded[moduleName] then
        return __bundle_cache[moduleName]
    end

    local moduleSource = __bundle_sources[moduleName]
    if not moduleSource then
        error(string.format("5AM bundle module %q does not exist", tostring(moduleName)), 2)
    end
    if __bundle_loading[moduleName] then
        error(string.format("Circular 5AM bundle dependency involving %q", tostring(moduleName)), 2)
    end

    __bundle_loading[moduleName] = true
    local moduleChunk, compileError = __bundle_compiler(moduleSource)
    if type(moduleChunk) ~= "function" then
        __bundle_loading[moduleName] = nil
        error(string.format("Failed to compile bundled module %q: %s", tostring(moduleName), tostring(compileError)), 0)
    end

    local moduleEnvironment = setmetatable({
        __FIVE_AM_BUNDLED = __FIVE_AM_BUNDLED,
        __bundle_require = __bundle_require,
    }, {
        __index = __bundle_base_environment,
        __newindex = __bundle_base_environment,
    })
    __bundle_set_environment(moduleChunk, moduleEnvironment)

    local success, valueOrError = pcall(moduleChunk)
    __bundle_loading[moduleName] = nil

    if not success then
        error(string.format("Failed to load bundled module %q: %s", tostring(moduleName), tostring(valueOrError)), 0)
    end
    if valueOrError == nil then
        error(string.format("Bundled module %q returned nil", tostring(moduleName)), 0)
    end

    __bundle_cache[moduleName] = valueOrError
    __bundle_loaded[moduleName] = true
    return valueOrError
end

local __loader = __bundle_require("loader/init")
local __ui = __bundle_require("ui/init")
local __universal = __bundle_require("games/_universal/init")
local __registry = __loader.RegistryClass.new(nil)
local __registered, __registrationError = __registry:RegisterUniversal(__universal)
if not __registered then
    error(string.format("5AM universal module registration failed: %s", tostring(__registrationError)), 0)
end
__registry.Discover = false

local __environment = __loader.Utils:GetEnvironment()
local __providedKey = __environment.FiveAMKey or __environment.HubKey
if (type(__providedKey) ~= "string" or __providedKey == "") and type(__environment._G) == "table" then
    __providedKey = __environment._G.FiveAMKey or __environment._G.HubKey
end

local __startResult = __loader:Start({
    Key = __providedKey,
    UI = __ui,
    Registry = __registry,
})
__loader.LastStartResult = __startResult
if not __startResult.Success then
    error(string.format("5AM Hub startup failed [%s]: %s", tostring(__startResult.Code), tostring(__startResult.Message)), 0)
end
if type(__startResult.Game) ~= "table" or __startResult.Game.Success ~= true then
    local gameMessage = if type(__startResult.Game) == "table" then __startResult.Game.Message else "No game result was returned"
    local gameErrors = if type(__startResult.Game) == "table" then __startResult.Game.Errors else nil
    if type(gameErrors) == "table" and gameErrors[1] then
        gameMessage = string.format("%s (%s: %s)", tostring(gameMessage), tostring(gameErrors[1].Code), tostring(gameErrors[1].Message))
    end
    error(string.format("5AM Hub module initialization failed: %s", tostring(gameMessage)), 0)
end

return __loader
